(window.NTDATA=window.NTDATA||{});(NTDATA.cass=NTDATA.cass||{}).jn={"1":{"1":"В начале было Слово, и Слово было с Богом, и\nСлово было Бог.","2":"Оно было в начале с Богом,","3":"Все чрез Него возникло, и без Него ничто не\nвозникло, что возникло.","4":"В Нем была жизнь, и жизнь была свет людям.","5":"И свет во тьме светит, и тьма его не объяла.","6":"Явился человек, посланный от Бога, имя ему\nИоанн.","7":"Он\nпришел\nдля\nсвидетельства,\nчтобы\nсвидетельствовать о Свете, чтобы все уверовали чрез\nнего.","8":"Не\nбыл\nон\nСвет,\nно\nпришел,\nчтобы\nсвидетельствовать о Свете.","9":"Был Свет истинный, Который просвещает каждого\nчеловека, приходящего в мир.","10":"В мире Он был, и мир чрез Него возник, и мир Его\nне познал.","11":"К своим пришел, и свои Его не приняли.","12":"Всем же, кто принял Его, – дал им власть стать\nдетьми Божиими, верующим во имя Его,","13":"которые не от крови, и не от хотения плоти, и не\nот хотения мужа, но от Бога были рождены.","14":"И Слово стало плотью и обитало среди нас, и мы\nувидели славу Его, славу как Единородного от Отца,\nполного благодати и истины.","15":"Иоанн свидетельствует о Нем и провозглашает:\nэто был Тот, о Ком я сказал: Идущий за мною впереди\nменя стал, потому что прежде меня был.","16":"Ибо из полноты Его мы все приняли: и благодать\nна благодать;","17":"потому\nчто\nЗакон\nдан\nбыл\nчрез\nМоисея,\nблагодать и истина явились чрез Иисуса Христа.","18":"Бога никто не видел никогда: Единородный Бог,\nсущий в лоне Отца, Он открыл.","19":"И вот свидетельство Иоанна, когда послали к\nнему Иудеи из Иерусалима священников и левитов\nспросить его: ты кто?","20":"И он исповедал и не отрекся, и исповедал: я не\nХристос.","21":"И спросили его: что же? Ты Илия? И говорит: я не\nИлия. Ты пророк? И ответил: нет.","22":"Сказали тогда ему: кто ты, чтобы дать нам ответ\nпославшим нас? Что говоришь ты о самом себе?","23":"Он сказал: я голос вопиющего в пустыне:\nвыпрямьте дорогу Господу, как сказал Исаия пророк.","24":"А посланные были из фарисеев.","25":"И спросили его и сказали ему: что же ты\nкрестишь, если ты не Христос, и не Илия, и не пророк?","26":"Ответил им Иоанн, говоря: я крещу водою;\nпосреди вас стоит Тот, Кого вы не знаете:","27":"Идущий за мною, Который впереди меня стал.\nКому я недостоин развязать ремень обуви Его.","28":"Это произошло в Вифании, по ту сторону\nИордана, где Иоанн крестил.","29":"На другой день видит он Иисуса, идущего к нему,\nи говорит: вот Агнец Божий, Который берет грех мира.","30":"Это Тот, о Ком я сказал: за мною идет Муж,\nКоторый впереди меня стал, потому что прежде меня\nбыл.","31":"И я не знал Его, но для того пришел я крестить\nводою, чтобы Он явлен был Израилю.","32":"И засвидетельствовал Иоанн, говоря: я увидел\nДуха, сходящего, как голубь, с неба, и Он пребыл на\nНем.","33":"И я не знал Его, но Пославший меня крестить\nводою,\nТот\nмне\nсказал:\n«на\nКом\nувидишь\nДуха\nсходящего и пребывающего на Нем, Он есть крестящий\nДухом Святым».","34":"И я увидел и засвидетельствовал, что Он есть\nСын Божий.","35":"На другой день снова стоял Иоанн, и из учеников\nего двое.","36":"И взглянув на проходящего Иисуса, он говорит:\nвот Агнец Божий.","37":"И услышали оба ученика его слова и последовали\nза Иисусом.","38":"Обернувшись и увидев, что они идут следом,\nИисус говорит им: что вы ищете? Они сказали Ему:\nРавви (что значит: Учитель), где Ты пребываешь?","39":"Говорит им: идите и увидите. И пошли они и\nувидели, где Он пребывает, и пребыли у Него день тот.\nБыло около десятого часа.","40":"Андрей, брат Симона Петра, был один из двоих,\nуслышавших от Иоанна и последовавших за Ним.","41":"Первым находит он брата своего Симона и\nговорит ему: мы нашли Мессию (что в переводе значит:\nХристос).","42":"Привел он его к Иисусу. Взглянув на него, Иисус\nсказал: ты Симон, сын Иоанна, ты будешь называться\nКифа (что значит в переводе: Петр).","43":"На другой день захотел Он идти в Галилею и\nнаходит Филиппа. И говорит ему Иисус: следуй за Мною.","44":"Был же Филипп из Вифсаиды, из города Андрея и\nПетра.","45":"Находит Филипп Нафанаила и говорит ему: Того,\nо Ком написал Моисей в Законе и Пророки, мы нашли:\nИисуса, сына Иосифа, из Назарета.","46":"И сказал ему Нафанаил: из Назарета может ли\nбыть что доброе? Говорит ему Филипп: иди и посмотри.","47":"Увидел Иисус Нафанаила, идущего к Нему, и\nговорит о нем: вот, воистину, Израильтянин, в котором\nнет притворства.","48":"Говорит Ему Нафанаил: откуда Ты меня знаешь?\nОтветил Иисус и сказал ему: прежде чем позвал тебя\nФилипп, когда ты был под смоковницей, Я видел тебя.","49":"Ответил Ему Нафанаил: Равви, Ты Сын Божий, Ты\nЦарь Израилев.","50":"Ответил Иисус и сказал ему: оттого что Я сказал\nтебе: «Я видел тебя под смоковницей», ты веришь?\nУвидишь больше этого.","51":"И говорит ему: истинно, истинно говорю вам:\nувидите небо отверстым, и ангелов Божиих восходящих\nи нисходящих на Сына Человеческого."},"2":{"1":"И в третий день был брак в Кане Галилейской, и\nбыла Мать Иисуса там.","2":"Был зван также Иисус и ученики Его на брак.","3":"И когда недостало вина, Мать Иисуса говорит Ему:\nвина у них нет.","4":"И говорит Ей Иисус: что Мне и Тебе, женщина?\nЕще не пришел час Мой.","5":"Говорит Мать Его слугам: сделайте всё, что Он вам\nскажет.","6":"Стояли там каменные сосуды для воды, числом\nшесть, для очищений Иудейских, вмещавшие по две или\nтри меры.","7":"Говорит им Иисус: наполните сосуды водой; и\nнаполнили их доверху.","8":"И говорит им: зачерпните теперь и несите к\nраспорядителю пира. Они понесли.","9":"Когда же отведал распорядитель пира воды,\nсделавшейся вином – и не знал он, откуда оно: знали\nслуги, черпавшие воду, – зовет жениха распорядитель\nпира","10":"и говорит ему: каждый человек сперва доброе\nвино ставит, и когда опьянеют, худшее: ты же сохранил\nдоброе вино доселе.","11":"Так положил Иисус начало знамениям в Кане\nГалилейской и явил славу Свою, и уверовали в Него\nученики Его.","12":"После этого пришел Он в Капернаум: Сам и Мать\nЕго и братья Его и ученики Его, и там остались немного\nдней.","13":"И близко была Пасха Иудейская, и пришел Иисус\nв Иерусалим,","14":"и нашел в храме торгующих волами и овцами и\nголубями, и менял на своих местах.","15":"И сделав бич из веревок, выгнал из храма всех: и\nовец, и волов, и у менял рассыпал деньги, и столы\nопрокинул,","16":"и продающим голубей сказал: возьмите это\nотсюда, не делайте дома Отца Моего домом торговли.","17":"Вспомнили ученики Его, что в Писании сказано:\n«Ревность о доме Твоем пожрет Меня».","18":"Тогда ответили Иудеи и сказали Ему: какое\nзнамение можешь Ты дать нам, что властен так\nпоступать?","19":"Ответил Иисус и сказал им: разрушьте храм этот,\nи Я в три дня воздвигну его.","20":"Сказали Ему Иудеи: в сорок шесть лет был\nпостроен храм этот, и Ты в три дня воздвигнешь его?","21":"А Он говорил о храме тела Своего.","22":"Когда же Он воздвигнут был из мертвых,\nвспомнили ученики Его, что Он это говорил, и поверили\nПисанию и слову, которое сказал Иисус.","23":"А когда Он был в Иерусалиме на Пасхе в\nпраздник, многие уверовали во имя Его, видя Его\nзнамения, которые Он творил.","24":"Сам же Иисус не вверял Себя им оттого, что Он\nзнал всех,","25":"и потому что не имел нужды, чтобы кто\nзасвидетельствовал о человеке; ибо Сам знал, что было\nв человеке."},"3":{"1":"Был человек из фарисеев, имя ему Никодим,\nначальник Иудейский.","2":"Он пришел к Нему ночью и сказал Ему: Равви, мы\nзнаем, что Ты от Бога пришел учителем, ибо никто не\nможет творить те знамения, которые Ты творишь, если\nБог не с ним.","3":"Ответил Иисус и сказал ему: истинно, истинно\nговорю тебе: если кто не родится свыше, не может\nувидеть Царства Божия.","4":"Говорит\nЕму\nНикодим:\nкак\nможет\nчеловек\nродиться, будучи стар? Может ли он вторично войти в\nутробу матери своей и родиться?","5":"Ответил Иисус: истинно, истинно говорю тебе:\nесли кто не будет рожден от воды и Духа, не может\nвойти в Царство Божие.","6":"Рожденное от плоти есть плоть, и рожденное от\nДуха есть дух.","7":"Не удивляйся тому, что Я сказал тебе: нужно,\nчтобы вы родились свыше.","8":"Ветер, где хочет, веет, и голос его слышишь и не\nзнаешь, откуда приходит и куда уходит. Так – каждый\nрожденный от Духа.","9":"Ответил Никодим и сказал Ему: как может это\nбыть?","10":"Ответил Иисус и сказал ему: ты – учитель\nИзраильский, и этого не знаешь?","11":"Истинно, истинно говорю тебе: что мы знаем, о\nтом говорим, и что видели, о том свидетельствуем, и\nсвидетельства нашего вы не принимаете.","12":"Если Я о земном сказал вам, и вы не верите, – как\nповерите, если скажу вам о небесном?","13":"И никто еще не восходил на небо, только с неба\nСошедший, Сын Человеческий, сущий на небе.","14":"И как Моисей вознес змею в пустыне, так должен\nвознесён быть Сын Человеческий,","15":"чтобы каждый верующий имел в Нем жизнь\nвечную.","16":"Ибо так возлюбил Бог мир, что дал Сына\nЕдинородного, чтобы каждый верующий в Него не\nпогиб, но имел жизнь вечную.","17":"Ибо не послал Бог Сына в мир, чтобы судить мир,\nно чтобы мир спасён был чрез Него.","18":"Верующий в Него не судится; неверующий уже\nосужден, потому что не уверовал во имя Единородного\nСына Божия.","19":"А это есть суд, что свет пришел в мир, и\nвозлюбили люди больше тьму, чем свет; ибо были\nлукавы дела их.","20":"Ибо каждый, делающий злое, ненавидит свет и\nне идет к свету, чтобы не были изобличены дела его.","21":"А творящий истину идет к свету, чтобы были\nявлены дела его, что они в Боге соделаны.","22":"После этого пришел Иисус и ученики Его в\nИудейскую землю и там оставался с ними и крестил.","23":"Крестил и Иоанн в Еноне близ Салима, потому\nчто там было много воды, и приходили и крестились;","24":"ибо не был еще ввергнут в тюрьму Иоанн.","25":"Возник спор у учеников Иоанна с Иудеями по\nповоду очищения,","26":"и пришли к Иоанну и сказали ему: равви, Тот,\nКоторый был с тобой по ту сторону Иордана, о Котором\nты засвидетельствовал, вот Он крестит, и все идут к\nНему.","27":"Ответил Иоанн и сказал: не может человек брать\nна себя ничего, если не дано ему с неба.","28":"Вы сами о мне свидетельствуете, что я сказал: «я\nне Христос, но я послан перед Ним».","29":"Имеющий невесту есть жених, а друг жениха,\nстоящий и внимающий ему, радостию радуется голосу\nжениха. Эта радость моя теперь полна.","30":"Ему должно расти, а мне умаляться.","31":"Свыше Приходящий – выше всех; сущий от земли\n– земной и от земли говорит. С неба Приходящий – выше\nвсех.","32":"Что Он видел и слышал, о том свидетельствует, и\nсвидетельства Его никто не принимает.","33":"Принявший Его свидетельство печатью своею\nзаверил, что Бог истинен.","34":"Ибо Тот, Кого послал Бог, говорит слова Божии;\nибо не мерою дает Бог Духа.","35":"Отец любит Сына, и всё дал в руку Его.","36":"Верующий в Сына имеет жизнь вечную, а не\nпокоряющийся Сыну не увидит жизни, но гнев Божий\nпребывает на нем."},"4":{"1":"Итак, когда узнал Господь, что услышали фарисеи\nо том, что Иисус больше приобретает учеников и\nкрестит, чем Иоанн –","2":"впрочем, Сам Иисус не крестил, но ученики Его, –","3":"оставил Он Иудею и ушел снова в Галилею.","4":"И нужно было Ему проходить через Самарию.","5":"Итак,\nприходит\nОн\nв\nгород\nСамарийский,\nназываемый Сихарь, близ земли, которую дал Иаков\nИосифу, сыну своему.","6":"Был же там источник Иакова. Итак, Иисус,\nутомившись от дороги, сидел у источника. Было около\nшестого часа.","7":"Приходит женщина из Самарии почерпнуть воды.\nГоворит ей Иисус: дай Мне пить.","8":"Ибо ученики Его отлучились в город купить пищи.","9":"Говорит Ему женщина Самарянка: как Ты, Иудей,\nпросишь пить у меня, Самарянки ? Ибо не имеют Иудеи\nобщения с Самарянами.","10":"Ответил Иисус и сказал ей: если бы ты знала дар\nБожий, и Кто есть говорящий тебе: «дай Мне пить», – ты\nбы просила Его, и Он дал бы тебе воду живую.","11":"Говорит\nЕму\nженщина:\nгосподин,\nТебе\nи\nзачерпнуть нечем, и колодец глубок. Откуда же у Тебя\nвода живая?","12":"Разве Ты больше отца нашего Иакова, который\nдал нам колодец, и сам из него пил, и сыновья его, и\nскот его?","13":"Ответил Иисус и сказал ей: всякий, пьющий от\nводы этой, будет жаждать снова;","14":"тот же, кто будет пить от воды, которую Я дам\nему, не будет жаждать вовек, но вода, которую Я дам\nему, станет в нем источником воды, текущей в жизнь\nвечную.","15":"Говорит Ему женщина: господин, дай мне этой\nводы, чтобы мне не жаждать и не приходить сюда\nчерпать.","16":"Говорит ей Иисус: иди, позови мужа твоего и\nприходи сюда.","17":"Ответила женщина и сказала: у меня нет мужа.\nГоворит Иисус: хорошо ты сказала: «у меня нет мужа»,","18":"ибо было у тебя пять мужей, и тот, который у\nтебя теперь, тебе не муж. Это ты истину сказала.","19":"Говорит Ему женщина: господин, вижу, что Ты\nпророк.","20":"Отцы наши на этой горе поклонялись Богу, а вы\nговорите, что в Иерусалиме то место, где должно\nпоклоняться.","21":"Говорит ей Иисус: верь Мне, женщина, что\nприходит час, когда не на горе этой и не в Иерусалиме\nбудете поклоняться Отцу.","22":"Вы поклоняетесь тому, чего не знаете; мы\nпоклоняемся тому, что знаем, потому что спасение – от\nИудеев.","23":"Но приходит час, и теперь есть, когда истинные\nпоклонники будут поклоняться Отцу в духе и истине;\nибо и Отец ищет, чтобы такими были поклоняющиеся\nЕму.","24":"Бог есть дух, и поклоняющиеся Ему должны\nпоклоняться в духе и истине.","25":"Говорит Ему женщина: знаю, что Мессия грядет,\nназываемый Христос. Когда придет Он, то возвестит\nнам всё.","26":"Говорит ей Иисус: это Я, говорящий с тобой.","27":"Тут пришли ученики Его и удивлялись, что Он\nговорил с женщиной. Никто, однако, не сказал: что Ты\nищешь? или: о чем говоришь с ней?","28":"Оставила тогда женщина свой сосуд для воды и\nпошла в город и говорит людям:","29":"пойдите, посмотрите Человека, Который сказал\nмне всё, что я сделала. Уж не Христос ли Он?","30":"Вышли люди из города и направились к Нему.","31":"Тем временем просили Его ученики, говоря:\nРавви, ешь!","32":"Он же сказал им: у Меня есть пища, которой вы\nне знаете.","33":"Говорили тогда ученики друг другу: не принес ли\nЕму кто-нибудь поесть?","34":"Говорит им Иисус: пища Моя – творить волю\nПославшего Меня и совершить Его дело.","35":"Не вы ли говорите: «еще четыре месяца, и жатва\nнаступит»? Так вот, говорю вам: поднимите глаза ваши,\nи взгляните на нивы, как они уже побелели к жатве.","36":"Жнущий получает награду и собирает плод в\nжизнь вечную, чтобы вместе радовались и сеющий и\nжнущий.","37":"Ибо здесь оправдывается слово: один сеет, а\nдругой жнет.","38":"Я\nпослал\nвас\nжать\nто,\nнад\nчем\nне\nвы\nпотрудились: другие потрудились, и вы вошли в труд\nих.","39":"Из города же того многие Самаряне уверовали в\nНего по слову женщины, свидетельствовавшей: Он\nсказал мне всё, что я сделала.","40":"Поэтому, когда пришли к Нему Самаряне, они\nпросили Его остаться с ними. И Он остался там два дня.","41":"И еще больше народа уверовало по слову Его;","42":"и женщине говорили: уже не по твоим рассказам\nверуем; ибо мы сами услышали и знаем, что Он есть\nвоистину Спаситель мира.","43":"А по истечении этих двух дней, Он вышел оттуда\nв Галилею.","44":"Ибо Сам Иисус засвидетельствовал, что пророк в\nсвоем отечестве чести не имеет.","45":"Итак, когда Он пришел в Галилею, приняли Его\nГалилеяне,\nвидевшие\nвсё,\nчто\nОн\nсотворил\nв\nИерусалиме в Праздник: ибо и сами они ходили на\nПраздник.","46":"Итак, Он пришел снова в Кану Галилейскую, где\nОн претворил воду в вино. И был некий царский слуга,\nсын которого был болен в Капернауме.","47":"Он, услышав, что Иисус пришел из Иудеи в\nГалилею, пошел к Нему и просил Его придти и исцелить\nего сына: ибо он был при смерти.","48":"Тогда сказал ему Иисус: если знамений и чудес\nне увидите, вы не уверуете.","49":"Говорит Ему царский слуга: господин, приди,\nпока еще не умерло дитя мое.","50":"Говорит ему Иисус: иди, сын твой жив. Поверил\nчеловек слову, которое сказал Иисус, и пошел.","51":"И когда он уже был в пути, рабы его встретили\nего, говоря, что отрок его жив.","52":"Он спросил их о часе, когда ему стало лучше.\nОни сказали: вчера в седьмом часу оставила его\nгорячка.","53":"Узнал тогда отец, что это было в тот час, когда\nсказал ему Иисус: сын твой жив; и уверовал сам и весь\nдом его.","54":"Это уже во второй раз сотворил знамение Иисус,\nпридя из Иудеи в Галилею."},"5":{"1":"После этого был праздник Иудейский, и пришел\nИисус в Иерусалим.","2":"Есть в Иерусалиме у Овечьих ворот водоём,\nназываемый по-еврейски Вифезда, с пятью крытыми\nходами.","3":"В них лежало множество больных: слепых,\nхромых, сухих, ожидающих движения воды.","4":"Ибо ангел Господень, время от времени, сходил в\nводоём и возмущал воду, и первый, кто входил по\nвозмущении воды, выздоравливал, каким бы ни был\nодержим недугом.","5":"Был там некий человек, тридцать восемь лет\nстрадавший болезнью своей.","6":"Иисус, увидев его лежащим и узнав, что он уже\nмного времени болен, говорит ему: хочешь ли стать\nздоровым?","7":"Ответил Ему больной: господин, нет у меня\nчеловека,\nчтобы\nопустить\nменя\nв\nводоём,\nкогда\nвозмутится вода. А пока я иду, другой раньше меня\nспускается.","8":"Говорит ему Иисус: встань, возьми постель твою и\nходи.","9":"И тотчас стал здоровым человек, и взял постель\nсвою, и начал ходить. А была суббота в тот день.","10":"Поэтому говорили Иудеи исцеленному: сегодня\nсуббота, и нельзя тебе брать постели.","11":"Он же ответил им: Тот, Кто сделал меня\nздоровым, Он мне и сказал: «возьми постель твою и\nходи».","12":"Спросили его: кто этот Человек, Который сказал\nтебе: «возьми и ходи»?","13":"Исцеленный же не знал, кто Он. Ибо Иисус\nскрылся, пользуясь тем, что на этом месте была толпа.","14":"После этого нашел его Иисус в храме и сказал\nему: вот, ты стал здоровым; больше не греши, чтобы не\nслучилось с тобой чего худшего.","15":"Пошел человек и сказал Иудеям, что здоровым\nсделал его Иисус.","16":"Потому и начали гнать Иудеи Иисуса, что Он это\nделал в субботу.","17":"Но Он ответил им: Отец Мой доныне делает, и Я\nделаю.","18":"И потому тем более искали Иудеи убить Его, что\nОн не только нарушал субботу, но и Отцом Своим\nназывал Бога, делая Себя равным Богу.","19":"Сказал же им Иисус в ответ: истинно, истинно\nговорю вам: не может Сын творить Сам по Себе ничего,\nесли не видит Отца творящим: ибо, что Он творит, то и\nСын творит так же.","20":"Ибо Отец любит Сына и показывает Ему всё, что\nСам творит, и покажет Ему дела больше этих, чтобы вы\nудивлялись.","21":"Ибо, как Отец воздвигает мертвых и животворит,\nтак и Сын, кого хочет, животворит.","22":"Ибо и Отец не судит никого, но суд весь дал\nСыну,","23":"чтобы все чтили Сына, как чтут Отца. Кто не чтит\nСына, не чтит Отца, пославшего Его.","24":"Истинно,\nистинно\nговорю\nвам:\nслово\nМое\nслушающий и верящий Пославшему Меня имеет жизнь\nвечную и на суд не приходит, но перешел из смерти в\nжизнь.","25":"Истинно, истинно говорю вам: приходит час, и\nтеперь есть, когда мертвые услышат голос Сына Божия,\nи услышавшие оживут.","26":"Ибо, как Отец имеет жизнь в Самом Себе, так дал\nОн и Сыну иметь жизнь в Самом Себе,","27":"и дал Ему власть суд творить, потому что Он –\nсын человека.","28":"Не удивляйтесь этому, потому что приходит час,\nкогда все, находящиеся в могилах, услышат голос Его","29":"и выйдут: сотворившие благое – в воскресение\nжизни, сделавшие злое – в воскресение суда.","30":"Не могу Я Сам по Себе творить ничего: как\nслышу, сужу, и суд Мой праведен, потому что не ищу\nволи Моей, но воли Пославшего Меня.","31":"Если\nЯ\nсвидетельствую\nо\nСамом\nСебе,\nсвидетельство Мое не истинно.","32":"Свидетельствует о Мне Другой, и знаю, что\nистинно то свидетельство, которым Он свидетельствует\nо Мне.","33":"Вы посылали к Иоанну, и он засвидетельствовал\nоб истине.","34":"Не от человека Я принимаю свидетельство, но\nговорю это, чтобы вы были спасены.","35":"Он был светильник горящий и светящий, и вы\nхотели недолгое время возликовать при свете его.","36":"Но у Меня свидетельство больше Иоаннова: ибо\nдела, которые дал Мне Отец, чтобы Я совершил их,\nсамые эти дела, которые Я творю, свидетельствуют о\nМне, что Отец Меня послал.","37":"И\nпославший\nМеня\nОтец,\nОн\nи\nзасвидетельствовал о Мне. Вы и голоса Его никогда не\nслышали, и вида Его не видели,","38":"и слова Его не имеете, в вас пребывающего, ибо\nКого послал Он, Тому вы не верите.","39":"Вы исследуете Писания, потому что думаете в\nних иметь жизнь вечную. А они и свидетельствуют о\nМне.","40":"И вы не хотите придти ко Мне, чтобы иметь\nжизнь.","41":"Славы от людей Я не принимаю,","42":"но Я знаю вас, что любви Божией вы не имеете в\nсебе.","43":"Я пришел во имя Отца Моего, и вы не принимаете\nМеня; если другой придет во имя свое, того вы примете.","44":"Как можете вы уверовать, если принимаете\nславу друг от друга, а славы, которая от единого Бога,\nне ищете?","45":"Не думайте, что Я буду обвинять вас пред Отцом:\nесть обвинитель на вас – Моисей, на которого вы\nвозложили упование.","46":"Если бы вы верили Моисею, то верили бы и Мне,\nибо о Мне он написал.","47":"Если же вы его писаниям не верите, как Моим\nсловам поверите?"},"6":{"1":"После этого ушел Иисус на ту сторону моря\nГалилейского, или Тивериадского.","2":"И следовало за Ним много народа, потому что\nвидели знамения, которые Он творил над больными.","3":"Иисус взошел на гору и там сидел с учениками\nСвоими.","4":"А была близко Пасха, праздник Иудейский.","5":"Иисус, подняв глаза и увидев, что много народа\nидет к Нему, говорит Филиппу: где бы нам купить\nхлебов, чтобы они поели?","6":"Говорил же Он это, испытывая его, ибо Сам знал,\nчто будет делать.","7":"Ответил Ему Филипп: на двести динариев не\nдостать для них хлебов, чтобы каждый получил хотя бы\nнемного.","8":"Говорит Ему один из учеников Его, Андрей, брат\nСимона Петра:","9":"есть тут мальчик, и у него пять хлебов ячменных и\nдве рыбки. Но что это для такого множества?","10":"Сказал Иисус: велите людям возлечь. Было на\nэтом месте много травы. Итак возлегли: мужчины\nчислом около пяти тысяч.","11":"Взял хлебы и, воздав благодарение, раздал\nвозлежащим; также и рыбок, сколько хотели.","12":"Когда же они насытились, говорит Он ученикам\nСвоим: соберите оставшиеся куски, чтобы ничего не\nпропало.","13":"И собрали они и наполнили двенадцать коробов\nтеми кусками от пяти хлебов ячменных, которые\nостались у евших.","14":"Тогда люди, увидев знамение, сотворенное Им,\nстали говорить, что Он воистину тот пророк, который\nгрядет в мир.","15":"Сам же Иисус, узнав, что собираются придти и\nзахватить Его, чтобы сделать царем, удалился снова на\nгору один.","16":"Когда же настал вечер, спустились ученики Его к\nморю","17":"и, сев в лодку, держали путь на ту сторону моря\nв Капернаум. И темнота уже наступила, и еще не\nприходил к ним Иисус.","18":"И море, при сильном ветре, волновалось.","19":"Итак, пройдя на веслах стадий около двадцати\nпяти или тридцати, видят они, что Иисус идет по морю и\nприближается к лодке, и испугались.","20":"Он же говорит им: это Я, не бойтесь.","21":"Хотели они взять Его в лодку, и тотчас лодка\nоказалась у земли, куда они плыли.","22":"На другой день толпа, собравшаяся по ту\nсторону моря, увидела, что другой лодки, кроме одной,\nтам не было, и что Иисус не входил в лодку вместе с\nучениками Своими, но ученики Его отправились одни.","23":"Пришли другие лодки из Тивериады, близко к\nтому месту, где ели хлеб по благодарении Господнем.","24":"Когда же увидела толпа, что ни Иисуса там нет,\nни учеников Его, сами сели они в лодки и пришли в\nКапернаум, ища Иисуса.","25":"И найдя Его по ту сторону моря, сказали Ему:\nРавви, когда Ты сюда прибыл?","26":"Ответил им Иисус и сказал: истинно, истинно\nговорю вам: вы ищете Меня не потому, что видели\nзнамения, а потому что поели хлебов и насытились.","27":"Делайте себе не пищу тленную, но пищу,\nпребывающую в жизнь вечную, которую вам даст Сын\nЧеловеческий. Ибо Его запечатлел Отец Бог.","28":"Тогда сказали они Ему: как нам поступать, чтобы\nделать дела Божии?","29":"Ответил Иисус и сказал им: в том дело Божие,\nчтобы вы верили в Того, Кого послал Он.","30":"Сказали Ему: какое же даешь Ты знамение,\nчтобы мы увидели и поверили Тебе? Что Ты делаешь?","31":"Отцы наши ели манну в пустыне, как написано:\n«Хлеб с неба дал им есть».","32":"Сказал же им Иисус: не Моисей дал вам хлеб с\nнеба, но Отец Мой дает вам истинный хлеб с неба.","33":"Ибо хлеб Божий есть Тот, Который сходит с неба\nи дает жизнь миру.","34":"Тогда сказали они Ему: Господи, давай нам\nвсегда этот хлеб.","35":"Сказал им Иисус: Я – хлеб жизни; приходящий ко\nМне не будет алкать, и верующий в Меня не будет\nжаждать никогда.","36":"Но Я сказал вам, что вы и видели Меня и не\nверуете.","37":"Всё, что дает Мне Отец, ко Мне придет, и\nприходящего ко Мне не изгоню вон,","38":"потому что Я сошел с неба не для того, чтобы\nтворить волю Мою, но волю Пославшего Меня.","39":"А воля Пославшего Меня – в том, чтобы из всего,\nчто Он дал Мне, Я не погубил ничего, но воскресил бы\nто в последний день.","40":"Ибо воля Отца Моего – в том, чтобы каждый,\nвидящий Сына и верующий в Него, имел жизнь вечную;\nи воскрешу его Я в последний день.","41":"Начали роптать на Него Иудеи за то, что Он\nсказал: Я – хлеб, сошедший с неба,","42":"и говорили: не Он ли Иисус, сын Иосифа, отца и\nмать Которого мы знаем? Как же Он теперь говорит: «Я\nсошел с неба»?","43":"Ответил Иисус и сказал им: не ропщите между\nсобою.","44":"Никто не может придти ко Мне, если Отец,\nпославший Меня, не привлечет его, и Я воскрешу его в\nпоследний день.","45":"Написано у Пророков: «И будут все научены\nБогом». Каждый, услышавший от Отца и научившийся,\nприходит ко Мне. –","46":"Не то, чтобы кто видел Отца, кроме Того, Кто от\nБога: Тот видел Отца. –","47":"Истинно, истинно говорю вам: тот, кто верует,\nимеет жизнь вечную.","48":"Я – хлеб жизни.","49":"Отцы ваши ели в пустыне манну и умерли.","50":"Этот хлеб с неба сходит, чтобы человек от него\nвкусил и не умер.","51":"Я хлеб живой, с неба сошедший: если кто вкусит\nот этого хлеба, жив будет вовек, и хлеб, который Я дам,\nесть плоть Моя, которую Я дам за жизнь мира.","52":"Тогда начали спорить между собой Иудеи,\nговоря: как может Он дать нам есть плоть?","53":"Сказал им Иисус: истинно, истинно говорю вам:\nесли вы не едите плоти Сына Человеческого и не пьете\nЕго крови, не имеете жизни в себе.","54":"Ядущий Мою плоть и пиющий Мою кровь имеет\nжизнь вечную, и Я воскрешу его в последний день.","55":"Ибо плоть Моя есть истинная пища, и кровь Моя\nесть истинное питие.","56":"Ядущий Мою плоть и пиющий Мою кровь во Мне\nпребывает, и Я в нем.","57":"Как послал Меня Живой Отец, и Я живу Отцом, –\nи ядущий Меня, он тоже будет жить Мною.","58":"Этот хлеб с неба сошел: не так, как ели отцы и\nумерли. Ядущий этот хлеб жить будет вовек.","59":"Это сказал Он в синагоге, уча в Капернауме.","60":"Многие же слышавшие из учеников Его сказали:\nтрудно это слово. Кто может его слушать?","61":"Иисус, зная в Себе, что ропщут на это ученики\nЕго, сказал им: это ли вас соблазняет?","62":"Что же, если вы увидите, что Сын Человеческий\nвосходит туда, где был прежде?","63":"Дух животворит, плоть не приносит никакой\nпользы. Слова, которые Я сказал вам, это дух, и это\nжизнь.","64":"Но есть между вами такие, которые не веруют.\nИбо знал с самого начала Иисус, кто неверующие, и кто\nпредаст Его.","65":"И говорил Он: поэтому Я сказал вам, что никто не\nможет придти ко Мне, если не будет дано ему от Отца.","66":"С этого времени многие из учеников Его отстали\nи больше с Ним не ходили.","67":"Тогда сказал Иисус Двенадцати: не хотите ли и\nвы уйти?","68":"Ответил Ему Симон Петр: Господи, к кому мы\nпойдем? Ты имеешь слова жизни вечной,","69":"и мы уверовали и познали, что Ты – Христос,\nСвятой Божий.","70":"Ответил им Иисус: не Я ли вас, двенадцать,\nизбрал? И один из вас – диавол.","71":"А говорил Он об Иуде, сыне Симона Искариота.\nИбо ему, одному из Двенадцати, предстояло предать\nЕго."},"7":{"1":"И после этого ходил Иисус по Галилее; ибо по\nИудее Он не хотел ходить, потому что Иудеи искали Его\nубить.","2":"А был близко Иудейский праздник Кущей.","3":"Сказали Ему тогда братья Его: пойди отсюда и иди\nв Иудею, чтобы и ученики Твои увидели дела Твои,\nкоторые Ты творишь;","4":"ибо никто ничего не делает втайне, а хочет сам\nбыть на виду: если Ты это делаешь, яви Себя миру.","5":"Ибо и братья Его не верили в Него.","6":"Говорит им на это Иисус: время Мое еще не\nпришло; а для вас всегда время.","7":"Не\nможет\nмир\nненавидеть\nвас.\nМеня\nже\nненавидит, потому что Я свидетельствую о нем, что\nдела его лукавы.","8":"Вы пойдите на праздник. Я еще не пойду на этот\nпраздник, потому что Мое время еще не исполнилось.","9":"И сказав им это, Он остался в Галилее.","10":"Когда же пошли братья Его на праздник, тогда и\nОн Сам пошел: не явно, а как бы втайне.","11":"Иудеи же искали Его на празднике и говорили:\nгде Он?","12":"И толков было много о Нем в народе. Одни\nговорили: Он добр; другие говорили: нет, но вводит\nнарод в заблуждение.","13":"Однако, никто открыто не говорил о Нем из\nстраха перед Иудеями.","14":"Когда праздник был уже на половине, вошел\nИисус в храм и учил.","15":"Удивлялись Иудеи, говоря: каким образом Он\nзнает Писания, не пройдя учения?","16":"Ответил им Иисус и сказал: Мое учение не Мое,\nно Пославшего Меня.","17":"Если кто хочет творить волю Его, он узнает об\nэтом учении, от Бога ли оно, или Я от Себя говорю.","18":"Говорящий от себя ищет собственной славы: но\nИщущий\nславы\nПославшего\nЕго,\nТот\nистинен,\nи\nнеправды в Нем нет.","19":"Не Моисей ли вам дал Закон? И никто из вас не\nисполняет Закона. Почему Меня ищете убить?","20":"Ответил народ: бес в Тебе, кто Тебя ищет убить?","21":"Ответил Иисус и сказал им: одно дело Я\nсотворил, и вы все удивляетесь ему.","22":"Моисей дал вам обрезание, – не то, чтобы оно\nбыло от Моисея, оно от отцов, – и в субботу вы\nобрезываете человека.","23":"Если обрезание принимает человек в субботу,\nчтобы не был нарушен Закон Моисеев, на Меня ли вы\nзлобствуете, что Я всего человека сделал здоровым в\nсубботу?","24":"Не по виду судите, но судите праведным судом.","25":"Говорили тогда некоторые из Иерусалимлян: не\nТот ли это, Кого ищут убить?","26":"И вот Он открыто держит речь, и ничего Ему не\nговорят. Неужели же воистину узнали начальники, что\nэто – Христос?","27":"Но Этого мы знаем, откуда Он. А когда Христос\nпридет, никто не будет знать, откуда Он.","28":"Возгласил тогда в храме Иисус, уча и говоря: и\nМеня знаете, и знаете, откуда Я, и не от Себя Я пришел,\nно истинен Пославший Меня, Которого вы не знаете.","29":"Я знаю Его, потому что Я – от Него, и Он Меня\nпослал.","30":"Искали Его схватить, и никто не наложил на Него\nруки, потому что еще не пришел час Его.","31":"Из толпы же многие уверовали в Него и\nговорили: Христос, когда придет, неужели сотворит\nбольше знамений, чем Этот сотворил?","32":"Услышали фарисеи эти толки о Нем в толпе, и\nпослали\nпервосвященники\nи\nфарисеи\nслужителей,\nчтобы схватить Его.","33":"Тогда сказал Иисус: еще малое время Я с вами, и\nиду к Пославшему Меня;","34":"будете искать Меня, и не найдете; и, где Я, туда\nвы не можете пойти.","35":"Сказали тогда друг другу Иудеи: куда Он\nсобирается идти, что мы не найдем Его? Не в рассеяние\nли среди Еллинов собирается Он идти и учить Еллинов?","36":"Что это за слово, которое Он сказал: вы будете\nискать Меня, и не найдете; и, где Я, туда вы не можете\nпойти?","37":"В последний же, в великий день Праздника стоял\nИисус и возгласил, говоря: если кто жаждет, да идет ко\nМне и да пьет.","38":"Кто верует в Меня, как говорит Писание, из чрева\nего потекут реки воды живой.","39":"Это сказал Он о Духе, Которого должны были\nполучить верующие в Него. Ибо еще не было Духа,\nпотому что Иисус еще не был прославлен.","40":"Некоторые\nиз\nтолпы,\nуслышав\nэти\nслова,\nговорили: это, воистину, пророк.","41":"Другие говорили: это – Христос. А иные говорили:\nразве из Галилеи придет Христос?","42":"Не Писание ли сказало, что от семени Давидова и\nиз Вифлеема, того селения, где был Давид, придет\nХристос?","43":"И произошло тогда из-за Него разделение в\nтолпе:","44":"некоторые из них хотели схватить Его, но никто\nне наложил на Него рук.","45":"Итак, пришли служители к первосвященникам и\nфарисеям, и те им сказали: почему вы не привели Его?","46":"Ответили служители: никогда еще так не\nговорил человек, как говорит Этот Человек.","47":"И ответили им фарисеи: неужели и вас ввели в\nзаблуждение?","48":"Разве кто-нибудь из начальников уверовал в\nНего, или из фарисеев?","49":"Но толпа эта, не знающая Закона: прокляты они.","50":"Говорит им Никодим, приходивший к Нему\nраньше (был он один из них):","51":"разве Закон наш судит человека, не выслушав\nего прежде и не узнав, что он делает?","52":"Ответили и сказали ему: и ты не из Галилеи ли?\nИсследуй и убедись, что из Галилеи пророк не\nприходит.","53":"И отправились каждый в свой дом."},"8":{"1":"Иисус же отправился на гору Масличную.","2":"А утром снова пришел в храм, и весь народ\nприходил к Нему. Он сел и учил их.","3":"И приводят книжники и фарисеи женщину,\nзастигнутую\nв\nпрелюбодеянии,\nи,\nпоставив\nее\nпосредине,","4":"говорят Ему: Учитель, эта женщина застигнута на\nместе прелюбодеяния.","5":"А в Законе Моисей заповедал нам таких побивать\nкамнями. Итак, что Ты скажешь?","6":"Это они говорили, искушая Его, чтобы иметь\nобвинение против Него. Иисус же, низко наклонившись,\nпальцем писал на земле.","7":"А когда они упорно продолжали спрашивать Его,\nОн поднял голову и сказал им: кто из вас без греха,\nпервый брось в нее камень.","8":"И снова наклонившись, писал на земле.","9":"Они же, услышав, стали уходить один за другим,\nначиная со старших, и остался один Иисус и женщина\nпосредине.","10":"Иисус, подняв голову, говорит ей: женщина, где\nони? Никто тебя не осудил?","11":"Она же сказала: никто, Господи. Сказал Иисус: и\nЯ тебя не осуждаю. Иди, отныне больше не греши.","12":"Итак, снова говорил им Иисус: Я – свет миру. Тот,\nкто следует за Мною, не будет ходить во тьме, но будет\nиметь свет жизни.","13":"Тогда сказали Ему фарисеи: Ты о Себе Самом\nсвидетельствуешь. Свидетельство Твое не истинно.","14":"Ответил\nИисус\nи\nсказал\nим:\nхотя\nЯ\nи\nсвидетельствую о Себе Самом, истинно свидетельство\nМое, потому что Я знаю, откуда Я пришел и куда иду, вы\nже не знаете, откуда Я пришел или куда иду.","15":"Вы по плоти судите, Я не сужу никого.","16":"Если же и Я сужу, то суд Мой истинен, ибо Я не\nодин, но Я и Пославший Меня.","17":"И в Законе вашем написано, что свидетельство\nдвух человек истинно.","18":"Я\nсвидетельствую\nо\nСебе\nСамом,\nи\nсвидетельствует о Мне Пославший Меня Отец.","19":"Тогда говорили они Ему: где Отец Твой? Ответил\nИисус: ни Меня вы не знаете, ни Отца Моего. Если бы вы\nМеня знали, то и Отца Моего знали бы.","20":"Эти слова сказал Он у сокровищницы, уча в\nхраме; и никто не схватил Его, потому что еще не\nпришел час Его.","21":"Снова сказал Он им: Я иду, и будете искать Меня,\nи в грехе вашем умрете: куда Я иду, вы не можете\nпойти.","22":"Говорили тогда Иудеи: уж не убьет ли Он Себя,\nчто говорит: «куда Я иду, вы не можете пойти»?","23":"И Он говорил им: вы от нижних, Я от вышних; вы\nот сего мира, Я не от мира сего.","24":"Сказал же Я вам, что вы умрете в грехах ваших;\nибо если вы не уверуете, что Я есмь, умрете вы в грехах\nваших.","25":"Говорили Ему тогда: Ты кто? Сказал им Иисус: о\nчем Мне вообще говорить с вами?","26":"Много надо Мне говорить и судить о вас; но\nПославший Меня истинен, и что Я слышал от Него, это и\nговорю миру.","27":"Не поняли они, что говорил Он им об Отце.","28":"Поэтому сказал Иисус: когда вы вознесёте Сына\nЧеловеческого, тогда узнаете, что Я есмь, и от Себя не\nделаю ничего, но как научил Меня Отец, так говорю.","29":"И Пославший Меня со Мною: Он не оставил Меня\nодного, потому что Я делаю всегда угодное Ему.","30":"Когда Он это говорил, многие уверовали в Него.","31":"Говорил же Иисус к уверовавшим в Него Иудеям:\nесли вы пребудете в слове Моем, воистину вы ученики\nМои,","32":"и познаете истину, и истина освободит вас.","33":"Ответили они Ему: мы семя Авраамово, и никому\nне были рабами никогда. Как же Ты говоришь: «вы\nсделаетесь свободными»?","34":"Ответил им Иисус: истинно, истинно говорю вам:\nвсякий, делающий грех, есть раб греха.","35":"Но раб не пребывает в доме вовек; сын\nпребывает вовек.","36":"Итак, если Сын вас освободит, вы действительно\nсвободны будете.","37":"Знаю, что вы семя Авраамово; но вы ищете Меня\nубить, потому что слово Мое не вмещается в вас.","38":"Что Я видел у Отца Моего, то говорю, и вы, что\nслышали у отца вашего, то делаете.","39":"Ответили они и сказали Ему: отец наш Авраам.\nГоворит им Иисус: если бы вы были дети Авраамовы, вы\nделали бы дела Авраама.","40":"Теперь же вы ищете Меня убить: Человека,\nКоторый сказал вам истину, а услышал Я ее от Бога.\nЭтого Авраам не делал.","41":"Вы делаете дела отца вашего. Сказали Ему: мы\nне были рождены в блуде; один у нас Отец: Бог.","42":"Сказал им Иисус: если бы Бог был Отец ваш, вы\nлюбили бы Меня, ибо Я от Бога исшел и пришел: Я не\nСам от Себя пришел, но Он Меня послал.","43":"Почему вы речи Моей не понимаете? Потому что\nне можете слышать слова Моего.","44":"Вы – от отца вашего, диавола, и хотите делать\nпохоти отца вашего. Он человекоубийца был от начала\nи в истине не стоял, потому что нет истины в нем. Когда\nкто говорит ложь, говорит то, что ему свойственно,\nоттого что и отец его – лжец.","45":"А Мне, потому что Я говорю истину, вы не верите.","46":"Кто из вас обличит Меня в грехе? Если Я говорю\nистину, почему вы не верите Мне?","47":"Кто от Бога, слова Божии слышит; вы потому не\nслышите, что вы не от Бога.","48":"Ответили Иудеи и сказали Ему: не правильно ли\nмы сказали, что Ты – Самарянин, и бес в Тебе?","49":"Ответил Иисус: во Мне беса нет, но Я чту Отца\nМоего, а вы бесчестите Меня.","50":"Я же не ищу славы Моей: есть Ищущий и\nСудящий.","51":"Истинно, истинно говорю вам: если кто Мое слово\nсоблюдёт, не увидит смерти вовек.","52":"Сказали Ему Иудеи: теперь мы знаем, что в Тебе\nбес: Авраам умер и пророки, а Ты говоришь: «если кто\nслово Мое соблюдёт, не вкусит смерти вовек».","53":"Неужели Ты больше отца нашего Авраама,\nкоторый умер? И пророки умерли. Кем Ты Себя\nделаешь?","54":"Ответил Иисус: если Я Сам Себя прославляю,\nслава Моя – ничто: Отец Мой – вот Кто прославляет\nМеня, Он, о Ком вы говорите, что Он – Бог ваш.","55":"И вы не познали Его, Я же знаю Его. И если Я\nскажу, что не знаю Его, Я буду подобный вам лжец, но Я\nзнаю Его и слово Его соблюдаю.","56":"Авраам, отец ваш, возликовал, оттого что ему\nпредстояло видеть день Мой: и увидел и возрадовался.","57":"Тогда сказали Ему Иудеи: Тебе нет еще\nпятидесяти лет, и Ты видел Авраама?","58":"Сказал им Иисус: истинно, истинно говорю вам:\nпрежде чем Авраам был, Я есмь.","59":"Тогда взяли они камни, чтобы бросить в Него.\nИисус же скрылся и вышел из храма."},"9":{"1":"И проходя, Он увидел человека слепого от\nрождения.","2":"И спросили Его ученики Его, говоря: Равви, кто\nсогрешил: он или родители его, что слепым родился?","3":"Ответил Иисус: ни он не согрешил, ни родители\nего, но это для того, чтобы явлены были дела Божии на\nнем.","4":"Нам надо делать дела Пославшего Меня, доколе\nесть день: приходит ночь, когда никто не может делать.","5":"Пока Я в мире, Я свет миру.","6":"Сказав это, Он плюнул на землю, сделал смесь из\nслюны и помазал ему смесью глаза,","7":"и сказал ему: иди, умойся в водоёме Силоам (что\nзначит в переводе: Посланный). Он пошел и умылся, и\nпришел зрячим.","8":"Тут соседи и видевшие его раньше, потому что\nбыл он нищий, стали говорить: не тот ли это, кто здесь\nсидит и просит милостыню?","9":"Одни говорили: это он; другие говорили: нет, но\nпохож на него. Он говорил: это я.","10":"Сказали ему тогда: как же открылись твои глаза?","11":"Он ответил: Человек, называемый Иисус, сделал\nсмесь и помазал мне глаза и сказал мне: иди в Силоам и\nумойся. Пошел я и, умывшись, прозрел.","12":"И сказали ему: где Он? Он говорит: не знаю.","13":"Ведут его к фарисеям, этого бывшего слепца.","14":"А была суббота в тот день, когда сделал смесь\nИисус и открыл ему глаза.","15":"Снова начали спрашивать его фарисеи, как он\nпрозрел. Он же сказал им: смесь положил Он мне на\nглаза, и умылся я, и вижу.","16":"Сказали тогда некоторые из фарисеев: не от\nБога Этот Человек, потому что субботы не соблюдает.\nДругие же говорили: как может человек грешный\nтворить\nтакие\nзнамения?\nИ\nбыло\nмежду\nними\nразделение.","17":"Тогда снова говорят слепому: чтоб скажешь о\nНем ты, Он ведь открыл тебе глаза? И тот сказал: Он\nпророк.","18":"Не поверили тогда Иудеи о нем, что он был слеп\nи\nпрозрел,\nпока\nне\nпризвали\nродителей\nсамого\nпрозревшего","19":"и не спросили их: ваш это сын, о котором вы\nговорите, что он родился слепым? Как же он теперь\nвидит?","20":"И ответили родители его и сказали: мы знаем,\nчто это наш сын, и что он родился слепым;","21":"а как он теперь видит, не знаем, или кто открыл\nему глаза, мы не знаем; его спросите, он взрослый, сам\nо себе скажет.","22":"Это сказали родители его, оттого что боялись\nИудеев; ибо Иудеи уже согласились между собой: если\nкто исповедает Его Христом, да будет отлучен от\nсинагоги.","23":"Поэтому родители его сказали: он взрослый, его\nспросите.","24":"Итак, призвали человека вторично, того, кто был\nслеп, и сказали ему: воздай славу Богу; мы знаем, что\nЧеловек Тот грешник.","25":"Он же ответил: грешник ли Он, я не знаю; одно\nзнаю, что слеп был и теперь вижу.","26":"Сказали ему: что Он сделал тебе? Как открыл\nтебе глаза?","27":"Он ответил им: я уже сказал вам, и вы не\nуслышали. Почему снова хотите слушать? Не хотите ли\nи вы сделаться Его учениками?","28":"И обругали они его и сказали: ты ученик Того, а\nмы Моисеевы ученики.","29":"Мы знаем, что Моисею говорил Бог, а об Этом мы\nне знаем, откуда Он.","30":"Ответил человек и сказал им: это и удивительно,\nчто вы не знаете, откуда Он, а Он открыл мне глаза.","31":"Мы знаем, что грешников Бог не слушает: но\nесли кто боится Бога и волю Его творит, того слушает.","32":"От века не было слышно, чтобы кто открыл глаза\nслепорожденному.","33":"Если бы не был Он от Бога, не мог бы творить\nничего.","34":"Ответили они и сказали ему: в грехах ты весь\nродился, и ты учишь нас? И выгнали его вон.","35":"Услышал Иисус, что выгнали его вон, и, найдя\nего, сказал; веруешь ты в Сына Человеческого?","36":"Тот ответил и сказал: а кто Он, Господи, чтобы я\nуверовал в Него?","37":"Сказал ему Иисус: и видел ты Его, и Говорящий с\nтобою – это Он.","38":"И он сказал: верую, Господи, и поклонился Ему.","39":"И сказал Иисус: на суд пришел Я в мир сей, чтобы\nневидящие видели, и видящие стали слепы.","40":"Услышали это те из фарисеев, которые были с\nНим, и сказали Ему: неужели и мы слепы?","41":"Сказал им Иисус: если бы вы были слепы, не\nимели бы греха. Ныне же вы говорите: «мы видим».\nГрех ваш пребывает."},"10":{"1":"Истинно, истинно говорю вам: кто не через дверь\nвходит во двор овчий, а влезает иным путем, – тот вор и\nразбойник;","2":"а кто входит через дверь, – тот пастырь овцам,","3":"Ему привратник отворяет, и овцы голос его\nслышат, и своих овец он зовет по имени и выводит их.","4":"И когда он всех своих выгонит, – впереди их идет,\nи овцы за ним следуют, потому что знают голос его.","5":"А за чужим не последуют, но побегут от него,\nпотому что не знают голоса чужих.","6":"Эту притчу сказал им Иисус: они же не поняли, что\nзначило то, что Он им говорил.","7":"Снова сказал Иисус: истинно, истинно говорю вам:\nЯ – дверь овцам.","8":"Все,\nкто\nни\nприходили\nдо\nМеня,\nворы\nи\nразбойники, но не послушали их овцы.","9":"Я – дверь: чрез Меня если кто войдет, спасен\nбудет, и войдет и выйдет и пастбище найдет.","10":"Вор приходит только для того, чтобы украсть и\nубить и погубить. Я пришел, чтобы жизнь имели и в\nизбытке имели.","11":"Я – пастырь добрый. Пастырь добрый душу свою\nполагает за овец.","12":"Наемник, а не пастырь, тот, кому овцы не свои,\nвидит, как волк приходит, и оставляет овец и бежит (и\nволк их похищает и разгоняет),","13":"потому что он наемник, и нет ему дела до овец.","14":"Я – пастырь добрый, и знаю Моих, и знают Меня\nМои.","15":"Как знает Меня Отец, знаю и Я Отца; и душу Мою\nполагаю за овец.","16":"И другие овцы есть у Меня – не из этого двора, и\nтех Мне надлежит привести, и голос Мой они услышат,\nи будет одно стадо, один Пастырь.","17":"Потому любит Меня Отец, что Я полагаю душу\nМою, чтобы снова принять ее.","18":"Никто не брал ее от Меня, но Я полагаю ее Сам.\nВласть имею положить ее, и власть имею снова принять\nее. Эту заповедь Я получил от Отца Моего.","19":"Снова произошло разделение между Иудеями из-\nза этих слов.","20":"Говорили многие из них: в Нем бес, и Он\nбезумствует. Что Его слушаете?","21":"Другие говорили: это – слова не бесноватого:\nможет ли бес открывать глаза слепым?","22":"Настал\nтогда\nпраздник\nОбновления\nв\nИерусалиме; была зима.","23":"И ходил Иисус в храме, в Притворе Соломоновом.","24":"Тогда окружили Его Иудеи и говорили Ему:\nдоколе будешь Ты томить душу нашу? Если Ты Христос,\nскажи нам открыто.","25":"Ответил им Иисус: Я сказал вам, и вы не верите;\nдела, которые Я творю во имя Отца Моего, они\nсвидетельствуют о Мне;","26":"но вы не верите, потому что вы не из овец Моих.","27":"Овцы Мои голос Мой слышат, и Я знаю их, и они\nследуют за Мною,","28":"и Я даю им жизнь вечную, и не погибнут они\nвовек, и не похитит их никто из руки Моей.","29":"Отец Мой, Который дал Мне дар, больше всех, и\nиз руки Отца не может похищать никто,","30":"Я и Отец – одно.","31":"Снова взяли камни Иудеи, чтобы побить Его.","32":"Ответил им Иисус: много добрых дел показал Я\nвам от Отца. За какое из этих дел побиваете вы Меня\nкамнями?","33":"Ответили Ему Иудеи: не за доброе дело мы\nпобиваем Тебя камнями, но за хулу и за то, что Ты,\nбудучи человеком, делаешь Себя Богом.","34":"Ответил им Иисус: не написано ли в Законе\nвашем: «Я сказал: вы – боги»?","35":"Если Закон назвал богами тех, к которым было\nслово Божие, а Писание не может быть упразднено, –","36":"Тому ли, Кого Отец освятил и послал в мир, вы\nговорите: «Ты богохульствуешь», потому что Я сказал:\n«Я – Сын Божий»?","37":"Если Я не творю дел Отца Моего, не верьте Мне.","38":"Если же творю, то, хотя бы Мне не верили, делам\nверьте, да познаете и знаете, что во Мне Отец, и Я в\nОтце.","39":"Тогда\nискали снова схватить Его, но Он\nуклонился от руки их.","40":"И пошел Он снова на ту сторону Иордана, на то\nместо, где Иоанн прежде крестил, и остался там.","41":"И многие пришли к Нему и говорили, что Иоанн\nзнамения не сотворил никакого, но всё, что сказал\nИоанн о Нем, было истинно.","42":"И многие уверовали в Него там."},"11":{"1":"А был болен один человек, Лазарь из Вифании, из\nселения Марии и Марфы, сестры ее.","2":"Мария же была та, которая помазала Господа\nмиром и отерла ноги Его волосами своими; ее брат\nЛазарь был болен.","3":"Послали сестры сказать Ему: Господи, вот тот,\nкого Ты любишь, болен.","4":"Услышав это, Иисус сказал: болезнь эта не к\nсмерти, но во славу Божию, чтобы прославлен был Сын\nБожий чрез нее.","5":"Любил Иисус Марфу и сестру ее и Лазаря.","6":"А когда услышал, что Лазарь болен, тогда остался\nОн два дня на том месте, где был.","7":"Затем, после этого, Он говорит ученикам: идем\nснова в Иудею.","8":"Говорят Ему ученики: Равви, только что искали\nИудеи побить Тебя камнями, и Ты снова идешь туда?","9":"Ответил Иисус: не двенадцать ли часов в дне? Кто\nходит днем, не спотыкается, потому что видит свет\nмира сего.","10":"А кто ходит ночью, спотыкается, потому что нет\nсвета в нем.","11":"Сказал Он это, и говорит им потом: Лазарь, друг\nнаш, уснул; но Я иду разбудить его.","12":"Сказали Ему ученики: Господи, если уснул, будет\nспасен.","13":"Но сказал Иисус о смерти его, а они подумали,\nчто говорит Он о простом сне.","14":"Тогда и сказал им Иисус прямо: Лазарь умер.","15":"Радуюсь за вас, что Я не был там, дабы вы\nуверовали. Но идем к нему.","16":"Тогда Фома, называемый Близнец, сказал другим\nученикам: идем и мы, чтобы умереть с Ним.","17":"Придя, Иисус нашел, что он уже четыре дня в\nгробнице.","18":"Была же Вифания близ Иерусалима, стадиях в\nпятнадцати.","19":"И многие из Иудеев пришли к Марфе и Марии\nутешить их в горе о брате.","20":"Марфа, когда услышала, что Иисус идет, вышла к\nНему навстречу; Мария же сидела у себя в доме.","21":"Сказала тогда Марфа Иисусу: Господи, если бы\nТы был здесь, не умер бы брат мой.","22":"Я и теперь знаю, что о чем бы Ты ни попросил\nБога, даст Тебе Бог.","23":"Говорит ей Иисус: воскреснет брат твой.","24":"Говорит Ему Марфа: знаю, что воскреснет в\nвоскресение, в последний день.","25":"Сказал ей Иисус: Я – воскресение и жизнь;\nверующий в Меня, если и умрет, оживет;","26":"и всякий живущий и верующий в Меня не умрет\nвовек. Веришь ли ты в это?","27":"Говорит она Ему: да. Господи, я уверовала и\nверую, что Ты – Христос, Сын Божий, грядущий в мир.","28":"И сказав это, она пошла и позвала Марию, сестру\nсвою, сказав тайно: Учитель здесь и зовет тебя.","29":"Она же, когда услышала, встала поспешно и\nпошла к Нему.","30":"Еще не вошел Иисус в селение, но всё еще был\nна том месте, где встретила Его Марфа.","31":"Тогда Иудеи, бывшие с ней в доме и утешавшие\nее, увидев, как Мария поспешно встала и вышла,\nпоследовали за ней, думая, что она идет к гробнице,\nчтобы плакать там.","32":"А Мария, когда пришла туда, где был Иисус,\nувидев Его, пала к Его ногам и сказала Ему: Господи,\nесли бы Ты был здесь, не умер бы мой брат.","33":"Иисус, когда увидел ее плачущую и пришедших с\nней Иудеев плачущих, возмутился духом и пришел в\nволнение,","34":"и сказал: где вы положили его? Говорят Ему:\nГосподи, иди и посмотри.","35":"Прослезился Иисус.","36":"Говорили тогда Иудеи: вот, как Он любил его.","37":"А некоторые из них сказали: не мог ли Он,\nоткрывший глаза слепому, сделать, чтобы и этот не\nумер?","38":"Иисус, снова возмущаясь в Себе, приходит к\nгробнице: это была пещера, и камень закрывал ее.","39":"Говорит Иисус: возьмите камень. Говорит ему\nсестра умершего, Марфа: Господи, уже смердит: ведь\nему четвертый день.","40":"Говорит ей Иисус: не сказал ли Я тебе, что, если\nуверуешь, увидишь славу Божию?","41":"Тогда взяли камень. Иисус же поднял глаза\nввысь и сказал: Отче, благодарю Тебя, что Ты услышал\nМеня.","42":"Я знал, что Ты всегда Меня слышишь, но сказал\nради народа, стоящего кругом, чтобы они уверовали,\nчто Ты Меня послал.","43":"И сказав это, воззвал громким голосом: Лазарь,\nвыходи.","44":"И вышел умерший, связанный по рукам и ногам\nпогребальными перевязями, и лицо его было обернуто\nплатком. Говорит им Иисус: развяжите его и пустите\nего идти.","45":"Тогда многие из Иудеев, пришедшие к Марии и\nувидевшие, что Он сотворил, уверовали в Него.","46":"А некоторые из них пошли к фарисеям и сказали\nим, что сотворил Иисус.","47":"Собрали тогда первосвященники и фарисеи\nсовещание и говорили: что нам делать, потому что Этот\nЧеловек много творит знамений?","48":"Если оставим Его так, все уверуют в Него, и\nпридут Римляне и уничтожат у нас и храм и народ.","49":"Один же из них, Каиафа, будучи на тот год\nпервосвященником, сказал им: вы не знаете ничего,","50":"и не разумеете, что лучше для вас, чтобы один\nчеловек умер за народ, а не весь народ погиб.","51":"Это он сказал не от себя, но будучи на тот год\nпервосвященником, пророчествовал, что предстояло\nИисусу умереть за народ, –","52":"и не за народ только, но для того, чтобы и\nрассеянных детей Божиих собрать воедино.","53":"С этого дня они приняли решение убить Его.","54":"Поэтому Иисус больше не ходил открыто между\nИудеями, но пошел оттуда в страну близ пустыни, в\nгород, называемый Ефраим, и там остался с учениками.","55":"А была близко Пасха Иудейская, и пришли\nмногие в Иерусалим из страны той перед Пасхой, чтобы\nочиститься.","56":"Искали тогда Иисуса и говорили между собой,\nстоя в храме: как вам кажется? Он, конечно, не придет\nна Праздник?","57":"А первосвященники и фарисеи дали приказ,\nчтобы, если кто узнает, где Он, донес, дабы схватить\nЕго."},"12":{"1":"Итак, Иисус за шесть дней до Пасхи пришел в\nВифанию, где был Лазарь, которого Иисус воздвиг из\nмертвых.","2":"Сделали Ему там вечерю, и Марфа служила.\nЛазарь же был одним из возлежащих с Ним.","3":"Тогда Мария, взяв фунт мира из нарда чистого,\nмногоценного, помазала ноги Иисуса и отерла волосами\nсвоими ноги Его, и дом наполнился благоуханием мира.","4":"И говорит Иуда Искариот, один из учеников Его,\nкоторому предстояло предать Его:","5":"почему не продали это миро за триста динариев и\nне дали нищим?","6":"Сказал же он это не потому, чтобы заботился о\nнищих, но потому, что был вор и, имея денежный ящик,\nбрал то, что туда опускали.","7":"Сказал тогда Иисус: оставь ее; нужно было, чтобы\nсберегла она миро на день погребения Моего.","8":"Ибо нищих вы всегда имеете с собою, Меня же не\nвсегда имеете.","9":"Узнало тогда много народа из Иудеев, что Он там,\nи пришли не ради Иисуса только, но чтобы и Лазаря\nувидеть, которого Он воздвиг из мертвых.","10":"Первосвященники же решили убить и Лазаря,","11":"потому что многие из Иудеев ради него\nприходили и веровали в Иисуса.","12":"На другой день много народа, пришедшего на\nПраздник, услышав, что Иисус идет в Иерусалим,","13":"взяли пальмовые ветви и вышли навстречу Ему и\nвосклицали: Осанна! Благословен Грядущий во имя\nГосподне и Царь Израилев!","14":"Иисус же, найдя осленка, сел на него, как\nнаписано:","15":"Не бойся, дочь Сиона: вот, Царь твой грядет,\nсидя на молодом осле.","16":"Этого ученики Его не поняли сперва, но когда\nбыл прославлен Иисус, тогда они вспомнили, что это\nбыло о Нем написано, и это сделали Ему.","17":"Свидетельствовал же народ, который был с Ним,\nкогда Он воззвал Лазаря из гробницы и воздвиг его из\nмертвых.","18":"Потому и вышел народ к Нему навстречу, что\nуслышали, что Он сотворил это знамение.","19":"Фарисеи же сказали друг другу: вы видите, что\nничего вы не достигаете, вот, мир пошел за Ним.","20":"Из шедших на поклонение в Праздник были\nнекоторые Еллины.","21":"Они пришли к Филиппу, который был из\nВифсаиды\nГалилейской,\nи\nпросили\nего,\nговоря:\nгосподин, мы хотим видеть Иисуса.","22":"Приходит Филипп и говорит Андрею; приходят\nАндрей и Филипп и говорят Иисусу.","23":"Иисус же отвечает им, говоря: пришел час быть\nпрославленным Сыну Человеческому.","24":"Истинно, истинно говорю вам: если зерно\nпшеничное, упав на землю, не умрет, оно остается одно;\nесли же умрет, приносит много плода.","25":"Любящий душу свою губит ее, и ненавидящий\nдушу свою в мире сем в жизнь вечную сохранит ее.","26":"Если Мне кто служит, за Мною да следует, и где\nЯ, там и слуга Мой будет. Если кто Мне служит, почтит\nего Отец.","27":"Теперь душа Моя смущена, и что Мне сказать?\nОтче, спаси Меня от часа сего; но ради этого Я пришел,\nна час сей.","28":"Отче, прославь Твое имя. Раздался тогда голос с\nнеба: и прославил и еще прославлю.","29":"Народ же, стоявший и слышавший, говорил: это\nгром. Другие говорили: ангел говорил с Ним.","30":"Ответил Иисус и сказал: не для Меня голос этот,\nно для вас.","31":"Теперь суд миру сему; теперь князь мира сего\nизвергнут будет вон.","32":"И Я, когда вознесён буду от земли, всех привлеку\nк Себе.","33":"Это Он говорил, давая понять, какою смертью\nпредстояло Ему умереть.","34":"Ответил Ему народ: мы слышали в Законе, что\nХристос пребывает вовек, а как же Ты говоришь, что\nдолжен быть вознесён Сын Человеческий? Кто этот Сын\nЧеловеческий?","35":"Сказал им Иисус: еще малое время свет между\nвами. Ходите, пока имеете свет, чтобы тьма вас не\nобъяла. И ходящий во тьме не знает, куда идет.","36":"Пока имеете свет, веруйте в свет, чтобы стать\nвам сынами света. Это сказал Иисус, и уйдя скрылся от\nних.","37":"После того, как Он столько знамений сотворил\nперед ними, они не верили в Него,","38":"дабы исполнилось слово Исаии пророка, которое\nон сказал: Господи, кто поверил слышанному от нас, и\nрука Господня кому открылась?","39":"Они потому не могли верить, что еще сказал\nИсаия:","40":"Он ослепил их глаза и сделал жёстким их\nсердце, чтобы не увидели они глазами и не поняли\nсердцем, и не обратились. И Я исцелю их.","41":"Это сказал Исаия, потому что увидел славу Его и\nсказал о Нем.","42":"Впрочем, и из начальников многие уверовали в\nНего, но из-за фарисеев не исповедывали, чтобы не\nбыть отлученными от синагоги;","43":"ибо возлюбили славу человеческую больше, чем\nславу Божию.","44":"Иисус же возгласил и сказал: верующий в Меня\nне в Меня верует, но в Пославшего Меня,","45":"и видящий Меня видит Пославшего Меня.","46":"Я в мир пришел, как свет, чтобы ни один\nверующий в Меня не пребыл во тьме.","47":"И если кто услышит Мои слова и не сохранит, Я\nне сужу его, ибо Я пришел не судить мир, но спасти\nмир.","48":"Для отвергающего Меня и не принимающего\nМоих слов есть судья: слово, которое Я изрек, оно будет\nсудить его в последний день.","49":"Потому что Я не от Себя изрек, но Пославший\nМеня Отец Сам Мне заповедь дал, что Мне сказать, и\nчто изречь.","50":"И знаю, что заповедь Его есть жизнь вечная.\nИтак, что Я говорю, – как сказал Мне Отец, так и\nговорю."},"13":{"1":"А перед праздником Пасхи, зная, что пришел Его\nчас перейти от мира сего к Отцу, Иисус, возлюбив\nСвоих, находящихся в мире, до конца возлюбил их.","2":"И во время вечери, когда диавол уже заронил в\nсердце Иуды Симонова Искариота намерение предать\nЕго,","3":"Он, зная, что Отец всё дал Ему в руку, и что Он от\nБога исшел и к Богу идет, –","4":"встает с вечери и снимает одежду. И взяв\nполотенце, Он опоясался.","5":"Затем льет воду в умывальницу. И начал мыть\nноги учеников и отирать полотенцем, которым был\nопоясан.","6":"Итак, подходит Он к Симону Петру, и тот говорит\nЕму: Господи, Ты ли мне моешь ноги?","7":"Ответил Иисус и сказал ему: что Я делаю, ты не\nзнаешь теперь, но поймешь потом.","8":"Говорит Ему Петр: не умоешь Ты моих ног вовек.\nОтветил ему Иисус: если не умою тебя, ты не имеешь\nчасти со Мною.","9":"Говорит Ему Симон Петр: Господи, не ноги мои\nтолько, но и руки и голову.","10":"Говорит ему Иисус: омытого нет нужды мыть,\nразве только его ноги, но он чист весь; и вы чисты, но\nне все.","11":"Ибо знал Он предающего Его; поэтому сказал: не\nвсе вы чисты.","12":"Когда же Он умыл их ноги и взял одежду Свою и\nвозлег снова, Он сказал им: знаете ли, что Я сделал\nвам?","13":"Вы называете Меня Учителем и Господом, и\nправильно говорите. Ибо Я действительно Учитель и\nГосподь.","14":"Итак, если Я умыл вам ноги, Я, Господь и\nУчитель, – и вы должны друг другу умывать ноги.","15":"Ибо Я дал вам пример для того, чтобы, как Я\nсделал вам, и вы делали.","16":"Истинно, истинно говорю вам: раб не больше\nгосподина своего, и посланец не больше пославшего\nего.","17":"Если вы это знаете, блаженны вы, когда делаете\nэто.","18":"Не о всех вас говорю: Я знаю, кого избрал. Но да\nисполнится Писание: «Ядущий со Мною хлеб поднял на\nМеня пяту свою».","19":"Говорю это вам уже теперь, прежде чем сбылось,\nдабы вы уверовали, когда сбудется, что Я есмь.","20":"Истинно, истинно говорю вам: если Я кого\nпошлю, то принимающий его Меня принимает, а Меня\nпринимающий принимает Пославшего Меня.","21":"Сказав это, Иисус был объят волнением в духе, и\nзасвидетельствовал, и сказал: истинно, истинно говорю\nвам: один из вас предаст Меня.","22":"Смотрели друг на друга ученики, недоумевая, о\nком Он говорит.","23":"Возлежал один из учеников Его у груди Иисуса:\nтот, которого любил Иисус.","24":"Делает ему знак Симон Петр и говорит: скажи,\nкто это, о ком Он говорит.","25":"Он, припав к груди Иисуса, говорит Ему: Господи,\nкто это?","26":"Отвечает Иисус: тот, кому Я обмакну и дам этот\nкусок. Обмакнув кусок, Он берет и дает Иуде, сыну\nСимона Искариота.","27":"И тогда, после этого куска, вошел в него сатана.\nГоворит ему Иисус: что делаешь, делай скорее.","28":"Но никто из возлежащих не понял, к чему Он\nсказал ему это.","29":"Ибо некоторые думали – так как у Иуды был\nденежный ящик, – что говорит ему Иисус: купи, что нам\nнужно к Празднику, или чтобы дал что-нибудь нищим.","30":"Взяв кусок, он вышел тотчас. Была ночь.","31":"Итак, когда он вышел, говорит Иисус: теперь\nпрославлен Сын Человеческий, и Бог прославлен в Нем.","32":"Если Бог прославлен в Нем, то и Бог прославит\nЕго в Себе, и тотчас прославит Его.","33":"Дети Мои, еще недолго Я с вами. Будете искать\nМеня, и, как Я сказал Иудеям: «куда Я иду, вы не\nможете пойти», так и вам говорю теперь.","34":"Заповедь новую даю вам: да любите друг друга;\nкак Я возлюбил вас, и вы да любите друг друга.","35":"По этому узнают все, что вы Мои ученики, если\nбудете иметь любовь между собою.","36":"Говорит Ему Симон Петр: Господи, куда Ты\nидешь? Ответил Ему Иисус: куда Я иду, ты не можешь\nтеперь последовать за Мною, но последуешь после.","37":"Говорит Ему Петр: Господи, почему я не могу за\nТобою последовать теперь? Я душу мою за Тебя положу.","38":"Отвечает Иисус: душу твою за Меня положишь?\nИстинно, истинно говорю тебе: петух не пропоет, как ты\nотречешься от Меня трижды."},"14":{"1":"Да не смущается сердце ваше: веруйте в Бога и в\nМеня веруйте.","2":"В доме Отца Моего обителей много. А если бы не\nбыло, разве Я сказал бы вам: иду приготовить место\nвам?","3":"И когда пойду и приготовлю место вам, снова\nприду и возьму вас к Себе, чтобы, где Я, и вы были.","4":"А куда Я иду, вы знаете, и путь знаете.","5":"Говорит Ему Фома: Господи, мы не знаем, куда Ты\nидешь; как же нам знать путь?","6":"Говорит ему Иисус: Я – путь и истина и жизнь;\nникто не приходит к Отцу иначе, как чрез Меня.","7":"Если бы вы знали Меня, то и Отца Моего знали бы.\nИ отныне вы знаете Его и видели Его.","8":"Говорит Ему Филипп: Господи, покажи нам Отца, и\nэтого нам довольно.","9":"Говорит ему Иисус: столько времени Я с вами, и ты\nне познал Меня, Филипп? Кто Меня увидел, увидел\nОтца. Как же ты говоришь: «покажи нам Отца»?","10":"Не веришь ты, что Я в Отце, и Отец во Мне? Те\nслова, которые Я говорю вам, Я не от Себя говорю:\nОтец, во Мне пребывающий, творит дела Свои.","11":"Верьте Мне, что Я в Отце, и Отец во Мне. Если же\nнет, по самым делам верьте.","12":"Истинно, истинно говорю вам: верующий в Меня\nбудет творить дела, которые Я творю, и большие этих\nбудет творить, потому что Я иду к Отцу.","13":"И о чем ни попросите во имя Мое, Я сотворю,\nчтобы прославлен был Отец в Сыне.","14":"Если о чем попросите Меня во имя Мое, Я\nсотворю.","15":"Если любите Меня, заповеди Мои соблюдите.","16":"И Я умолю Отца, и другого Утешителя даст вам,\nчтобы был с вами вовек,","17":"Духа Истины, Которого мир не может принять,\nпотому что не видит Его и не знает; вы же знаете Его,\nпотому что Он с вами пребывает и в вас будет.","18":"Не оставлю вас сиротами: приду к вам.","19":"Еще недолго, и уже мир Меня не видит; но вы\nвидите Меня, потому что Я живу, и вы жить будете.","20":"В тот день узнаете вы, что Я в Отце Моем, и вы\nво Мне, и Я в вас.","21":"Имеющий заповеди Мои и соблюдающий их, тот и\nесть любящий Меня. А любящий Меня возлюблен будет\nОтцом Моим, и Я возлюблю его и явлю ему Себя.","22":"Говорит Ему Иуда, не Искариот: Господи, что это,\nчто Ты нам хочешь являть Себя, а не миру?","23":"Ответил Иисус и сказал ему: если кто любит\nМеня, слово Мое соблюдет, и Отец Мой возлюбит его, и\nк нему Мы придем и обитель Себе у него сотворим.","24":"Не любящий Меня слов Моих не соблюдает. А\nслово, которое вы слышите, не Мое, но пославшего\nМеня Отца.","25":"Это Я сказал вам, с вами пребывая.","26":"Утешитель же, Дух Святой, Которого пошлет\nОтец во имя Мое, Он вас научит всему и напомнит вам\nвсё, что сказал вам Я.","27":"Мир оставляю вам, мир Мой даю вам: не так, как\nмир дает, Я даю вам. Да не смущается сердце ваше и да\nне робеет.","28":"Вы слышали, что Я сказал вам: «ухожу и приду к\nвам». Если бы вы любили Меня, вы возрадовались бы,\nчто Я иду к Отцу, потому что Отец больше Меня.","29":"И теперь Я сказал вам прежде, чем сбылось,\nчтобы, когда сбудется, вы уверовали.","30":"Я уже не буду много говорить с вами: ибо идет\nкнязь мира, и во Мне не имеет ничего.","31":"Но чтобы мир узнал, что Я люблю Отца и, как\nзаповедал Мне Отец, так творю: вставайте, идем\nотсюда."},"15":{"1":"Я – истинная виноградная лоза, и Отец Мой –\nвиноградарь.","2":"Всякую ветвь на Мне, не приносящую плода, Он\nудаляет, и всякую, приносящую плод, очищает, чтобы\nбольший плод приносила.","3":"Вы уже чисты чрез слово, которое Я сказал вам.","4":"Пребудьте во Мне, и Я – в вас. Как ветвь не может\nприносить плода сама собой, если не пребывает на\nлозе, так не можете и вы, если во Мне не пребываете.","5":"Я – лоза, вы – ветви. Пребывающий во Мне – и Я в\nнем, – тот приносит много плода, потому что без Меня\nне можете творить ничего.","6":"Если кто не пребывает во Мне, – он выброшен вон,\nкак ветвь, и засох; и собирают их и в огонь бросают, и\nони сгорают.","7":"Если пребудете во Мне, и слова Мои в вас\nпребудут, – о всём, что хотите, просите, и будет вам.","8":"В том слава Отца Моего, чтобы вы много плода\nприносили и стали Моими учениками.","9":"Как возлюбил Меня Отец, и Я вас возлюбил:\nпребудьте в любви Моей.","10":"Если вы заповеди Мои соблюдете, вы пребудете в\nлюбви Моей, как Я заповеди Отца Моего соблюл и\nпребываю в Его любви.","11":"Это сказал Я вам, чтобы радость Моя в вас была,\nи радость ваша была полна.","12":"Это – заповедь Моя: да любите друг друга, как Я\nвозлюбил вас.","13":"Больше той любви никто не имеет, как кто душу\nсвою положит за друзей своих.","14":"Вы друзья Мои, если делаете то, что Я заповедую\nвам.","15":"Я уже не называю вас рабами, потому что раб не\nзнает, что делает его господин; но вас Я назвал\nдрузьями, потому что всё, что услышал от Отца Моего, Я\nповедал вам.","16":"Не вы Меня избрали, но Я избрал вас и поставил\nвас, чтобы вы шли и плод приносили, и плод ваш\nпребывал бы, чтобы, о чём бы ни попросили вы Отца во\nимя Мое, дал Он вам.","17":"Это и заповедую вам: да любите друг друга.","18":"Если мир вас ненавидит, знайте, что Меня он\nпрежде вас возненавидел.","19":"Если бы вы от мира были, мир любил бы свое. А\nтак как вы не от мира, но Я избрал вас от мира, поэтому\nненавидит вас мир.","20":"Помните слово, которое Я сказал вам: раб не\nбольше господина своего. Если Меня гнали, и вас будут\nгнать;\nесли\nслово\nМое\nсоблюли,\nи\nваше\nбудут\nсоблюдать.","21":"Но это всё будут делать вам за имя Мое, потому\nчто не знают Пославшего Меня.","22":"Если бы Я не пришел и не говорил им, они не\nимели бы греха; теперь же извинения не имеют в грехе\nсвоем.","23":"Ненавидящий Меня и Отца Моего ненавидит.","24":"Если бы Я не сотворил между ними дел, каких\nникто другой не сотворил, они не имели бы греха;\nтеперь же и видели и возненавидели и Меня и Отца\nМоего.","25":"Но да исполнится слово, в Законе их написанное:\n«Возненавидели Меня напрасно».","26":"Когда придет Утешитель, Которого Я пошлю вам\nот Отца, Дух Истины, Который от Отца исходит, Он\nбудет свидетельствовать о Мне.","27":"Но и вы свидетельствуйте, потому что от начала\nвы со Мною."},"16":{"1":"Это Я сказал вам, чтобы вас не ввели в соблазн.","2":"Будут отлучать вас от синагог; но приходит час,\nкогда всякий, кто убьет вас, будет думать, что он\nприносит службу Богу.","3":"И это они будут делать, потому что не познали ни\nОтца, ни Меня.","4":"Но это Я сказал вам, чтобы вы помнили, когда\nпридет тому час, что о том Я сказал вам. А не сказал\nвам этого сначала, потому что был с вами.","5":"Теперь же иду к Пославшему Меня, и никто из вас\nне спрашивает Меня: куда идешь?","6":"Но от того, что Я это высказал вам, печаль\nнаполнила ваше сердце.","7":"Но Я истину говорю вам: лучше вам, чтобы Я ушел.\nИбо, если Я не уйду, Утешитель не придет к вам; если\nже пойду, пошлю Его к вам.","8":"И придя, Он явит миру его заблуждение о грехе и\nо праведности и о суде:","9":"о грехе, что не веруют в Меня;","10":"о праведности же, что Я к Отцу иду, и больше вы\nне видите Меня;","11":"о суде же, что князь мира сего осужден.","12":"Еще многое имею вам сказать, но теперь вам не\nпод силу.","13":"Когда же придет Он, Дух Истины, Он введет вас\nво всю истину, ибо Он не будет говорить от Себя, но\nбудет говорить то, что слышит, и грядущее возвестит\nвам.","14":"Он Меня прославит, оттого что от Моего возьмет\nи возвестит вам.","15":"Всё, что имеет Отец, Мое. Поэтому Я сказал, что\nОн от Моего берет и возвестит вам.","16":"Недолго уже, и вы больше не видите Меня; и\nопять недолго, и вы увидите Меня.","17":"Сказали тогда некоторые из учеников друг\nдругу: что это Он говорит нам: «недолго уже, и вы не\nвидите Меня; и опять недолго, и вы увидите Меня», и:\n«Я иду к Отцу»?","18":"Итак, они говорили: что это такое, что Он\nговорит: «недолго»? Не знаем, что Он говорит.","19":"Узнал Иисус, что хотели Его спрашивать, и\nсказал им: о том ли вы рассуждаете друг с другом, что\nЯ сказал: «недолго уже, и вы не видите Меня; и опять\nнедолго, и вы увидите Меня»?","20":"Истинно, истинно говорю вам: вы будете плакать\nи рыдать, а мир будет радоваться; вы печальны будете,\nно печаль ваша в радость обратится.","21":"Женщина, когда рождает, печаль имеет, потому\nчто пришел час ее; когда же родит дитя, уже не помнит\nскорби от радости, что родился человек в мир.","22":"И вы теперь печаль имеете; но Я снова увижу\nвас, и возрадуется ваше сердце, и радости вашей никто\nне отнимет у вас.","23":"И в тот день вы Меня не спросите ни о чем.\nИстинно, истинно говорю вам: если о чем попросите\nОтца, даст вам во имя Мое.","24":"Доныне вы не просили ни о чем во имя Мое:\nпросите и получите, чтобы радость ваша была полна.","25":"Это Я в притчах сказал вам: наступает час, когда\nЯ уже не в притчах буду говорить вам, но открыто об\nОтце возвещу вам.","26":"В тот день будете просить во имя Мое, и не\nговорю вам, что Я буду молить Отца о вас.","27":"Ибо Сам Отец любит вас, потому что вы Меня\nвозлюбили и уверовали, что Я от Бога исшел.","28":"Исшел от Отца и пришел в мир; снова оставляю\nмир и иду к Отцу.","29":"Говорят ученики Его: вот теперь Ты открыто\nговоришь, и притчи никакой не говоришь.","30":"Теперь мы знаем, что Ты знаешь всё, и не\nимеешь нужды, чтобы кто Тебя вопрошал. По этому\nверуем, что Ты от Бога исшел.","31":"Ответил им Иисус: теперь веруете?","32":"Вот приходит час, и пришел, что вы рассеетесь,\nкаждый к себе, и Меня оставите одного; но Я не один,\nпотому что Отец со Мною.","33":"Это сказал Я вам, чтобы вы во Мне мир имели. В\nмире скорбь имеете; но дерзайте: Я победил мир."},"17":{"1":"Это изрек Иисус и, подняв глаза Свои к небу,\nсказал: Отче, пришел час. Прославь Твоего Сына, чтобы\nСын прославил Тебя,","2":"так как Ты дал Ему власть над всякою плотью,\nчтобы всем, кого даровал Ты Ему, дал Он жизнь вечную.","3":"А жизнь вечная в том, чтобы знали Тебя, единого\nистинного Бога, и Кого Ты послал: Иисуса Христа.","4":"Я Тебя прославил на земле, совершив дело,\nкоторое Ты дал Мне сотворить.","5":"И теперь прославь Меня Ты, Отче, у Тебя Самого\nславою, которую Я имел, когда мира еще не было, у\nТебя.","6":"Я явил Твое имя людям, которых Ты дал Мне от\nмира. Твои были они, и Мне Ты их дал, и слово Твое они\nсоблюли.","7":"Теперь познали они, что всё, что Ты дал Мне, – от\nТебя,","8":"потому что слова, которые Ты дал Мне, Я дал им, и\nони приняли и познали воистину, что Я от Тебя исшел, и\nуверовали, что Ты Меня послал.","9":"Я о них молю, не о мире молю, но о тех, кого Ты\nдаровал Мне, потому что они – Твои;","10":"и всё Мое – Твое, и Твое – Мое, и Я прославлен в\nних.","11":"И Я уже не в мире, а они в мире, и Я к Тебе иду.\nОтче Святой, соблюди их во имя Твое, которое Ты дал\nМне, чтобы они были едино, как Мы.","12":"Когда Я был с ними, Я соблюдал их во имя Твое,\nкоторое Ты дал Мне, и сохранил, и никто из них не\nпогиб,\nкроме\nсына\nпогибели,\nдабы\nисполнилось\nПисание.","13":"Теперь же к Тебе иду, и говорю это в мире, чтобы\nрадость Моя в них была полна.","14":"Я дал им слово Твое, и мир возненавидел их,\nпотому что они не от мира, как Я не от мира.","15":"Я не молю, чтобы Ты взял их из мира, но чтобы\nсоблюл их от лукавого.","16":"Они не от мира, как Я не от мира.","17":"Освяти их истиною: слово Твое – истина.","18":"Как Ты послал Меня в мир, – и Я послал их в мир;","19":"и за них Я посвящаю Себя, чтобы и они были\nосвящены истиною.","20":"И не о них только молю, но и о верующих в Меня\nпо слову их,","21":"чтобы все едино были, как Ты, Отче, во Мне, и Я в\nТебе, чтобы и они в нас были, чтобы веровал мир, что Ты\nМеня послал.","22":"И славу, которую Ты даровал Мне, Я даровал им,\nда будут едино, как Мы едино.","23":"Я в них, и Ты во Мне, да будут они совершенны во\nедино, чтобы знал мир, что Ты Меня послал и возлюбил\nих, как Меня возлюбил.","24":"Отче! То, что Ты даровал Мне, – хочу, чтобы, где\nЯ, и они были со Мною, да видят славу Мою, которую Ты\nдаровал Мне, потому что возлюбил Меня прежде\nоснования мира.","25":"Отче праведный, и мир Тебя не познал, но Я Тебя\nпознал, и они познали, что Ты Меня послал.","26":"И Я поведал им имя Твое и поведаю, чтобы\nлюбовь, которою Ты возлюбил Меня, в них была, и Я в\nних."},"18":{"1":"Сказав это, Иисус вышел с учениками Своими на\nту сторону потока Кедрона, где был сад, в который\nвошел Сам и ученики Его.","2":"Знал же и Иуда, предававший Его, это место,\nпотому что часто собирался там Иисус с учениками\nСвоими.","3":"Итак, Иуда, взяв когорту, а от первосвященников и\nфарисеев – служителей, приходит туда с фонарями и\nфакелами и оружием.","4":"Иисус же, зная всё предстоящее Ему, вышел и\nговорит им: кого ищете?","5":"Ответили Ему: Иисуса Назорея. Говорит им Иисус:\nЯ есмь. Стоял же и Иуда, предававший Его, с ними.","6":"Итак, когда Он сказал им: Я есмь, они отступили\nназад и упали на землю.","7":"Тогда Он снова спросил их: кого ищете? Они\nсказали: Иисуса Назорея.","8":"Ответил Иисус: Я сказал вам, что Я есмь. Итак,\nесли Меня ищете, оставьте этих, пусть идут.","9":"Да исполнится слово, которое Он сказал: из тех,\nкого Ты даровал Мне, Я не погубил никого.","10":"Симон же Петр, у которого был меч, обнажил его\nи ударил первосвященникова раба, и отсек ему правое\nухо; было же имя рабу Малх.","11":"Сказал Иисус Петру: вложи меч в ножны. Чашу,\nкоторую дал Мне Отец, неужели Я не стану пить ее?","12":"Итак, когорта и трибун и служители Иудейские\nвзяли Иисуса и связали Его,","13":"и отвели Его сперва к Анне, ибо он был тесть\nКаиафы, который был на тот год первосвященником.","14":"Был же Каиафа тот, кто дал совет Иудеям, что\nлучше одному человеку умереть за народ.","15":"Следовал за Иисусом Симон Петр и другой\nученик. Ученик же тот был известен первосвященнику и\nвошел вместе с Иисусом во двор первосвященника;","16":"а Петр стоял у двери снаружи. Вышел тогда тот\nученик, другой, известный первосвященнику, и сказал\nпривратнице и ввел Петра.","17":"Говорит тогда Петру служанка-привратница: и\nты не из учеников ли Этого Человека? Говорит он: нет.","18":"И стояли рабы и служители: они разожгли\nуголья, потому что было холодно, и грелись. А с ними и\nПетр стоял и грелся.","19":"Первосвященник же спросил Иисуса об учениках\nЕго и об учении Его.","20":"Ответил ему Иисус: Я всё открыто сказал миру; Я\nвсегда учил в синагогах и в храме, где все Иудеи\nсобираются, и тайно не говорил ничего.","21":"Почему\nты\nМеня\nспрашиваешь?\nСпроси\nслышавших, что Я говорил им. Они знают, что сказал Я.","22":"Когда же Он сказал это, один из служителей,\nстоявший поблизости, ударил Иисуса в лицо и сказал:\nтак-то отвечаешь Ты первосвященнику?","23":"Ответил ему Иисус: если Я плохо сказал,\nсвидетельствуй о том, что плохо. Если хорошо, почему\nты Меня бьешь?","24":"Тогда послал Его Анна связанным к Каиафе,\nпервосвященнику.","25":"А Симон Петр всё стоял и грелся. Сказали тогда\nему: и ты не из учеников ли Его? Он отрекся и сказал:\nнет.","26":"Говорит\nодин\nиз\nрабов\nпервосвященника,\nродственник того, кому Петр отсек ухо: не я ли тебя\nвидел в саду с Ним?","27":"Тогда снова отрекся Петр, и тотчас пропел петух.","28":"Итак, ведут Иисуса от Каиафы в преторию. Было\nутро, и сами они не вошли в преторию, чтобы не\nоскверниться, но есть пасху.","29":"Вышел к ним Пилат наружу и говорит: какое\nобвинение выставляете вы против Этого Человека?","30":"Ответили они и сказали ему: если бы Он не делал\nзла, мы не предали бы Его тебе.","31":"Сказал им тогда Пилат: возьмите Его вы и по\nзакону вашему судите Его. Сказали ему Иудеи: нам не\nразрешается казнить никого;","32":"да исполнится слово Иисуса, которое Он сказал,\nдавая понять, какою смертью предстояло Ему умирать.","33":"Тогда Пилат вошел снова в преторию и призвал\nИисуса и сказал Ему: Ты – Царь Иудейский?","34":"Ответил Иисус: от себя ли ты это говоришь, или\nдругие сказали тебе о Мне?","35":"Ответил Пилат: разве я Иудей? Народ Твой и\nпервосвященники предали Тебя мне. Что Ты сделал?","36":"Ответил Иисус: Царство Мое не от мира сего.\nЕсли бы от мира сего было Царство Мое, служители Мои\nборолись бы за то, чтобы Я не был предан Иудеям.\nТеперь же Царство Мое не отсюда.","37":"Сказал Ему тогда Пилат: значит, Ты всё-таки\nЦарь? Ответил Иисус; ты говоришь, что Я Царь. Я на то\nродился и на то пришел в мир, чтобы свидетельствовать\nоб истине. Всякий, кто от истины, слушает Моего\nголоса.","38":"Говорит Ему Пилат: что есть истина? И сказав\nэто, он снова вышел к Иудеям и говорит им: я никакой\nне нахожу в Нем вины.","39":"Есть же обыкновение у вас, чтобы я одного\nотпускал вам на Пасху. Итак, хотите, чтобы я отпустил\nвам Царя Иудейского?","40":"Тогда закричали они снова, говоря: не Этого, но\nВаравву. Был же Варавва разбойник."},"19":{"1":"Тогда взял Пилат Иисуса и подверг бичеванию.","2":"И воины, сплетя венец из терния, возложили Ему\nна голову, и в одеяние пурпурное облачили Его,","3":"и подходили к Нему и говорили: да здравствует\nЦарь Иудейский! И били Его по лицу.","4":"И снова вышел Пилат наружу и говорит им: вот, я\nвывожу Его к вам, чтобы вы знали, что я никакой вины\nне нахожу в Нем.","5":"Вышел тогда Иисус наружу в терновом венце и\nпурпурном одеянии. И говорит им Пилат: вот Человек.","6":"Когда\nже\nувидели\nЕго\nпервосвященники\nи\nслужители, они закричали: распни, распни. Говорит им\nПилат: возьмите Его вы и распните, ибо я не нахожу в\nНем вины.","7":"Ответили ему Иудеи: у нас есть Закон, и по Закону\nОн должен умереть, потому что сделал Себя Сыном\nБожиим.","8":"Когда услышал Пилат это слово, он еще сильнее\nустрашился,","9":"и вошел в преторию снова и говорит Иисусу:\nоткуда Ты? Иисус же ответа не дал ему.","10":"Говорит Ему тогда Пилат: мне ли не говоришь?\nРазве Ты не знаешь, что я власть имею отпустить Тебя,\nи власть имею распять Тебя?","11":"Ответил ему Иисус: ты не имел бы надо Мной\nникакой власти, если бы не было дано тебе свыше.\nПоэтому тот, кто Меня предал тебе, больший грех\nимеет.","12":"С этого времени Пилат искал отпустить Его. Но\nИудеи закричали, говоря: если ты Этого отпустишь, ты\nне друг кесарю. Всякий, делающий себя царем, восстает\nпротив кесаря.","13":"Пилат, услышав эти слова, вывел Иисуса наружу\nи сел для вершения суда на место, называемое\n«Каменным помостом», а по-еврейски Гаввафа.","14":"Была же пятница перед Пасхой, около шестого\nчаса. И говорит он Иудеям: вот Царь ваш.","15":"Тогда закричали они: долой, долой, распни Его!\nГоворит им Пилат: Царя ли вашего распну? Ответили\nпервосвященники: нет у нас царя, кроме кесаря.","16":"Тогда он предал Его им на распятие. Итак, взяли\nИисуса и повели.","17":"И неся Себе крест, Он вышел на место,\nназываемое Лобным, которое по-еврейски называется\nГолгофа,","18":"где Его распяли, и с Ним двух других, по обе Его\nстороны, посредине же Иисуса.","19":"И сделал надпись на доске Пилат и поставил на\nкресте. Было же написано: Иисус Назорей, Царь\nИудейский.","20":"Эту надпись на доске многие прочли из Иудеев,\nпотому что близко было от города то место, где был\nраспят Иисус, и было написано по-еврейски, по-римски,\nпо-гречески.","21":"Говорили\nже\nПилату\nпервосвященники\nИудейские: не пиши: «Царь Иудейский», но: «Он сказал:\nЯ Царь Иудейский».","22":"Ответил Пилат: что я написал, то написал.","23":"Воины же, когда распяли Иисуса, взяли одежды\nЕго и разделили на четыре части, каждому воину по\nчасти, и хитон. Был же хитон не сшитый, тканый\nцеликом с самого верха.","24":"Сказали они друг другу: не будем рвать его, но\nбросим о нем жребий, чей будет. Да исполнится\nПисание: Разделили одежды Мои между собою и об\nодеянии Моем бросили жребий. Воины это сделали.","25":"Стояли же у креста Иисуса Мать Его и сестра\nМатери Его, Мария Клеопова и Мария Магдалина.","26":"Иисус же, увидев Мать и ученика, близ стоящего,\nкоторого Он любил, говорит Матери: Женщина, вот сын\nТвой.","27":"Потом говорит ученику: вот Мать твоя. И с того\nчаса взял ученик Ее к себе.","28":"После\nэтого\nИисус,\nзная,\nчто\nуже\nвсё\nсовершилось,\nговорит,\nдабы\nсвершилось\nПисание:\nжажду.","29":"Стоял тут сосуд, полный уксуса. Тогда наткнув\nна копье губку, полную уксуса, поднесли к Его устам,","30":"И когда вкусил Иисус уксуса, Он сказал:\nсовершилось. И склонив голову, предал дух.","31":"А так как была пятница, то Иудеи, чтобы тела не\nостались на кресте в субботу – ибо день той субботы\nбыл день великий, – попросили Пилата перебить у них\nголени и снять их.","32":"Итак, пришли воины, и у первого перебили\nголени, и у другого, распятого с Ним.","33":"Придя же к Иисусу, они, когда увидели, что Он\nуже умер, не перебили у Него голеней,","34":"но один из воинов копьем пронзил Ему бок, и\nвышла тотчас кровь и вода.","35":"И видевший засвидетельствовал, и истинно его\nсвидетельство, и он знает, что истинное говорит, чтобы\nи вы верили.","36":"Ибо произошло это, да исполнится Писание:\nКость Его да не сокрушится.","37":"И еще другое Писание говорит: Будут смотреть\nна Того, Кого пронзили.","38":"А после этого попросил Пилата Иосиф из\nАримафеи, бывший учеником Иисуса, но тайным из\nстраха перед Иудеями, взять тело Иисуса. И разрешил\nПилат. Пришел он и взял тело Его.","39":"Пришел же и Никодим, приходивший к Нему в\nпервый раз ночью, и принес состав из смирны и алоя\nоколо ста фунтов.","40":"Взяли они тело Иисуса и обвили Его пеленами, с\nблаговониями, как обыкновенно погребают Иудеи.","41":"Был же сад на том месте, где Он распят был, и в\nсаду гробница новая, в которой еще никто не был\nположен.","42":"Там-то ради пятницы Иудейской, так как близко\nбыла гробница, положили Иисуса."},"20":{"1":"В первый же день недели Мария Магдалина\nприходит утром еще в темноте к гробнице и видит, что\nкамень взят с гробницы.","2":"Бежит и приходит она к Симону Петру и к другому\nученику, которого любил Иисус, и говорит им: взяли\nГоспода из гробницы, и не знаем, где положили Его.","3":"Вышел тогда Петр и другой ученик и направились\nк гробнице.","4":"Бежали они оба вместе, и другой ученик бежал\nскорее, опередил Петра и пришел первый к гробнице.","5":"И наклонившись, видит, что лежат пелены;\nоднако, не вошел.","6":"Приходит тогда и Симон Петр, следуя за ним. И\nвошел он в гробницу и видит, что пелены лежат,","7":"и что платок, который был на голове Его, не с\nпеленами лежит, но отдельно свернут на своем месте.","8":"Тогда-то вошел и другой ученик, пришедший\nпервым к гробнице, и увидел, и уверовал.","9":"Ибо они еще не знали Писания, что надлежит Ему\nвоскреснуть из мертвых.","10":"Итак, пошли опять к себе ученики.","11":"Мария же стояла у гробницы снаружи и плакала.\nИ вот, когда плакала, наклонилась она в гробницу","12":"и видит, что сидят два ангела в белом, один у\nголовы, а другой у ног, где лежало тело Иисуса.","13":"И говорят ей они: женщина, почему ты плачешь?\nГоворит им: потому что взяли Господа моего, и не знаю,\nгде положили Его.","14":"Сказав это, она обернулась назад и видит, что\nстоит Иисус. И не знала она, что это Иисус.","15":"Говорит ей Иисус: женщина, почему ты плачешь?\nКого ищешь? Она, думая, что это садовник, говорит Ему:\nгосподин, если ты унес Его, скажи мне, где ты положил\nЕго, и я Его возьму.","16":"Говорит ей Иисус: Мариам! Обернувшись, она\nговорит Ему по-еврейски: Раввуни (что значит: Учитель)!","17":"Говорит ей Иисус: не прикасайся ко Мне, ибо Я\nеще не восшел к Отцу; но иди к братьям Моим и скажи\nим: восхожу к Отцу Моему и Отцу вашему, и Богу Моему\nи Богу вашему.","18":"Приходит\nМария\nМагдалина\nи\nвозвещает\nученикам, что видела Господа, и Он это сказал ей.","19":"Вечером, в день тот, в первый день недели,\nкогда из страха перед Иудеями двери были затворены\nтам, где были ученики, – пришел Иисус и стал\nпосредине и говорит им: мир вам!","20":"И сказав это, Он показал им и руки и бок.\nВозрадовались ученики, увидев Господа.","21":"Сказал им Иисус снова: мир вам! Как послал\nМеня Отец, и Я посылаю вас.","22":"И сказав это, дунул и говорит им: примите Духа\nСвятого.","23":"Если кому отпустите грехи, отпущены им; если\nна ком удержите, удержаны.","24":"Фома же, один из Двенадцати, называемый\nБлизнец, не был с ними, когда приходил Иисус.","25":"Говорили ему другие ученики: мы видели\nГоспода. Он же сказал им: если не увижу на руках Его\nследа от гвоздей и не вложу пальца моего в место\nгвоздей и не вложу руки моей в бок Его, никак не\nповерю.","26":"И через восемь дней снова были ученики в доме,\nи Фома с ними. Приходит Иисус, когда двери были\nзатворены; и стал посредине и сказал: мир вам!","27":"Затем говорит Фоме: дай палец твой сюда и\nпосмотри на руки Мои, и дай руку твою и вложи в бок\nМой, и не будь неверующим, но верующим.","28":"Ответил Фома и сказал Ему: Господь мой и Бог\nмой!","29":"Говорит ему Иисус: ты потому уверовал, что\nувидел Меня. Блаженны не видевшие и поверившие.","30":"Много и других знамений сотворил Иисус перед\nучениками Своими, о которых не написано в книге этой.","31":"Об этих же написано, чтобы вы веровали, что\nИисус есть Христос, Сын Божий, и чтобы, веруя, имели\nжизнь во имя Его."},"21":{"1":"После этого явил Себя снова Иисус ученикам на\nморе Тивериадском, явил же так.","2":"Были вместе Симон Петр и Фома, называемый\nБлизнец, и Нафанаил из Каны Галилейской, и сыновья\nЗеведеевы, и из учеников Его двое других.","3":"Говорит им Симон Петр: иду ловить рыбу. Говорят\nему: идем и мы с тобой. Вышли и сели в лодку, и в ту\nночь не поймали ничего.","4":"И когда утро уже наступало, стал Иисус на берегу,\nно не знали ученики, что это Иисус.","5":"Говорит им Иисус: друзья, есть ли у вас что-\nнибудь к хлебу? Они ответили Ему: нет.","6":"Он же сказал им: закиньте сеть по правую сторону\nлодки, и найдете. Они закинули и уже не могли ее\nвытащить от множества рыбы.","7":"Говорит тогда ученик тот, которого любил Иисус,\nПетру: это Господь. Симон же Петр, услышав, что это\nГосподь, опоясался одеждой (ибо он был наг) и\nбросился в море.","8":"Другие же ученики приплыли в лодке (были они\nнедалеко от земли: около двухсот локтей), таща сеть с\nрыбой.","9":"Когда же они сошли на землю, видят разложенные\nгорящие уголья и рыбу, на них лежащую, и хлеб.","10":"Говорит им Иисус: принесите из тех рыб, что вы\nпоймали сейчас.","11":"Вошел Симон Петр в лодку и вытащил на землю\nсеть, полную больших рыб, числом сто пятьдесят три; и\nхотя их было столько, не разорвалась сеть.","12":"Говорит им Иисус: идите, ешьте. Никто из\nучеников не смел спросить Его: Ты Кто? – зная, что это\nГосподь.","13":"Приходит Иисус и берет хлеб и дает им, и рыбу\nтакже.","14":"Это уже в третий раз явился Иисус ученикам,\nвосстав из мертвых.","15":"Итак, когда они поели, говорит Симону Петру\nИисус: Симон, сын Иоанна, любишь ли ты Меня больше,\nчем они? Говорит Ему: да, Господи, Ты знаешь, что я\nлюблю Тебя. Говорит ему: паси ягнят Моих.","16":"Говорит ему снова, во второй раз: Симон, сын\nИоанна, любишь ли ты Меня? Говорит Ему: да, Господи,\nТы знаешь, что я люблю Тебя. Говорит ему: будь\nпастырем овец Моих.","17":"Говорит ему в третий раз: Симон, сын Иоанна,\nлюбишь ли ты Меня? Опечалился Петр, что Он сказал\nему в третий раз: любишь ли ты Меня? и сказал Ему:\nГосподи, всё Ты знаешь. Ты знаешь, что я люблю Тебя.\nГоворит ему Иисус: паси овец Моих.","18":"Истинно, истинно говорю тебе: когда ты был\nмолод, то опоясывал себя сам и шел, куда хотел; когда\nже состаришься, протянешь руки твои, и другой\nопояшет тебя и поведет, куда не хочешь.","19":"А это Он сказал, давая понять, какою смертью он\nпрославит Бога. И сказав это, говорит ему: следуй за\nМною.","20":"Обернувшись, Петр видит, что следом идет\nученик, которого любил Иисус, тот самый, который и\nприпал на вечери к груди Его и сказал: Господи, кто\nесть предающий Тебя?","21":"Итак, увидев его, Петр говорит Иисусу: Господи,\nа он что?","22":"Говорит ему Иисус: если Я хочу, чтобы он\nпребывал, доколе Я не приду, что тебе? Ты за Мною\nследуй.","23":"Итак разнеслось это слово между братьями, что\nученик тот не умрет. Но не сказал ему Иисус, что он не\nумрет, но: если Я хочу, чтобы он пребывал, доколе Я не\nприду, что тебе?","24":"Он и есть тот ученик, который свидетельствует\nоб этом и написал это, и мы знаем, что истинно его\nсвидетельство.","25":"Есть же и многое другое, что сотворил Иисус:\nесли бы о всём том писалось, думаю, что и самому миру\nне вместить тех книг, которые стали бы писать."}};
